.sidebar-search-stats{font-size:10px;color:var(--text-tertiary);padding:4px 4px 0;font-family:'JetBrains Mono',monospace;display:none}
.sidebar-search-stats.visible{display:block}
.sidebar-search-highlight{background:rgba(110,86,207,0.35);color:var(--text-primary);border-radius:2px;padding:0 1px}
.conv-item-snippet{font-size:11px;color:var(--text-tertiary);margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;line-height:1.3}
.sidebar-search-empty{padding:24px 16px;text-align:center;color:var(--text-tertiary);font-size:12px;line-height:1.5}
.sidebar-search-empty-icon{font-size:28px;margin-bottom:8px;opacity:.5}
.search-loading{opacity:.6;font-style:italic}
@keyframes search-pulse{0%,100%{opacity:.6}50%{opacity:1}}.search-loading{animation:search-pulse 1.2s ease-in-out infinite}
/* Search toggle button active state */
#sidebarSearchToggle.active{color:var(--accent);background:var(--accent-subtle)}
/* ── Pinned zone + freeze border removed — pinning replaced by folders ── */
/* ── Scrollable list ── */
.conversations-list{flex:1;overflow-y:auto;padding:4px 8px 8px}
/* ── Collapsible date-group headers in the conversation list ── */
.conv-date-group{display:flex;align-items:center;gap:5px;width:100%;box-sizing:border-box;margin:0;padding:7px 8px 3px;background:var(--bg-secondary);border:none;cursor:pointer;user-select:none;font-family:inherit;font-size:10px;font-weight:700;letter-spacing:0.06em;text-transform:uppercase;color:var(--text-tertiary);position:sticky;top:0;z-index:1;transition:color .12s ease}
.conv-date-group:first-child{padding-top:2px}
.conv-date-group:hover{color:var(--text-secondary)}
.conv-date-chevron{flex-shrink:0;opacity:0.7;transition:transform .18s ease}
.conv-date-group.collapsed .conv-date-chevron{transform:rotate(-90deg)}
.conv-date-label{flex:1;text-align:left}
.conv-date-count{font-weight:600;font-size:10px;opacity:0.55;font-variant-numeric:tabular-nums}
/* ── Conversation item ── */
.conv-item{padding:10px 12px;border-radius:var(--radius-sm);cursor:pointer;transition:background var(--transition);margin-bottom:2px;display:flex;align-items:center;gap:10px;position:relative;overflow:hidden;contain:layout style;content-visibility:auto;contain-intrinsic-size:auto 56px}
.conv-item:hover{background:var(--bg-hover)}
.conv-item.active{background:var(--bg-active)}
.conv-item .conv-text{flex:1;min-width:0}
.conv-item .conv-title{font-size:13px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:flex;align-items:center;gap:5px;padding-right:4px}
.conv-feishu-badge{font-size:12px;flex-shrink:0;filter:grayscale(0.2);opacity:0.85}
/* Summarized-conversation glyph in the sidebar title. Quiet by default,
 * brightens on hover; click reveals the cached AI summary via a toast. */
.conv-summary-badge{display:inline-flex;align-items:center;flex-shrink:0;color:var(--text-tertiary);opacity:0.7;cursor:pointer;line-height:0;transition:opacity .12s,color .12s}
.conv-summary-badge:hover{opacity:1;color:var(--accent,#6ea8fe)}
/* Embedded memory list inside the Memory & Preferences settings tab — slightly
 * tighter than the modal, with a soft cap + scroll so it never dominates. */
.memory-list-embedded{margin-top:8px;max-height:340px;overflow-y:auto}
.settings-section-divider{height:1px;background:var(--border,rgba(255,255,255,.08));margin:18px 0 14px}
.conv-item .conv-date{display:flex;align-items:center;gap:4px;margin-top:3px}
.conv-date-text{font-size:11px;color:var(--text-tertiary)}
.conv-date-sep{font-size:9px;color:var(--text-tertiary);opacity:0.35}
.conv-date-time{font-family:'JetBrains Mono',monospace;font-size:10px;color:var(--text-tertiary);opacity:0.65;letter-spacing:-0.02em}
/* ── Status tags in sidebar date line ── */
.conv-status-tag{font-size:9px;font-weight:600;padding:1px 5px;border-radius:6px;line-height:14px;margin-left:4px;white-space:nowrap;animation:statusTagFadeIn .3s ease}
.conv-status-translating{color:#14b8a6;background:rgba(20,184,166,0.12)}
.conv-status-memprefetch{color:#eab308;background:rgba(234,179,8,0.12)}
.conv-status-streaming{color:var(--accent);background:var(--accent-subtle)}
.conv-status-error{color:#ef4444;background:rgba(239,68,68,0.12)}
.conv-status-incomplete{color:#f59e0b;background:rgba(245,158,11,0.12)}
@keyframes statusTagFadeIn{from{opacity:0;transform:translateX(-4px)}to{opacity:1;transform:translateX(0)}}
/* ── Overlay action buttons (gradient fade) ── */
.conv-actions{position:absolute;right:0;top:0;bottom:0;display:flex;align-items:center;gap:1px;padding:0 6px 0 24px;opacity:0;pointer-events:none;transition:opacity 0.15s ease;background:linear-gradient(90deg,transparent 0%,var(--bg-secondary) 40%)}
.conv-item:hover>.conv-actions{opacity:1;pointer-events:auto;background:linear-gradient(90deg,transparent 0%,var(--bg-hover) 40%)}
.conv-item.active>.conv-actions{background:linear-gradient(90deg,transparent 0%,var(--bg-active) 40%)}
.conv-item.active:hover>.conv-actions{opacity:1;pointer-events:auto;background:linear-gradient(90deg,transparent 0%,var(--bg-active) 40%)}
.conv-action-btn{display:flex;align-items:center;justify-content:center;width:28px;height:28px;border:none;background:none;color:var(--text-tertiary);cursor:pointer;border-radius:var(--radius-xs);transition:color 0.15s ease,background-color 0.15s ease}
.conv-action-btn:hover{background:rgba(255,255,255,0.08);color:var(--text-primary)}
/* conv-pin hover removed — replaced by folders */
.conv-action-btn.conv-delete:hover{color:var(--error-text);background:var(--error-bg)}

.conv-action-btn.conv-dup:hover{color:var(--accent)}
/* pinned hint removed — replaced by folders */
/* ── Streaming dot ── */
.conv-streaming-dot{width:8px;height:8px;border-radius:50%;background:var(--accent);flex-shrink:0;animation:pulse 1.5s infinite}
/* ── Translating dot — teal pulsing, visually distinct from streaming blue ── */
.conv-translating-dot{width:8px;height:8px;border-radius:50%;background:#14b8a6;flex-shrink:0;animation:translateDotPulse 1.2s ease-in-out infinite;box-shadow:0 0 5px rgba(20,184,166,0.4)}
@keyframes translateDotPulse{0%,100%{opacity:1;transform:scale(1);box-shadow:0 0 5px rgba(20,184,166,0.4)}50%{opacity:0.5;transform:scale(0.8);box-shadow:0 0 2px rgba(20,184,166,0.2)}}
/* ── Memory-prefetch dot — amber pulsing; matches the in-bubble chip color ── */
.conv-memprefetch-dot{width:8px;height:8px;border-radius:50%;background:#eab308;flex-shrink:0;animation:memPrefetchDotPulse 1.2s ease-in-out infinite;box-shadow:0 0 5px rgba(234,179,8,0.4)}
@keyframes memPrefetchDotPulse{0%,100%{opacity:1;transform:scale(1);box-shadow:0 0 5px rgba(234,179,8,0.4)}50%{opacity:0.5;transform:scale(0.8);box-shadow:0 0 2px rgba(234,179,8,0.2)}}
/* ── Awaiting-human dot — amber blinking, more prominent than streaming ── */
.conv-awaiting-human-dot{width:9px;height:9px;border-radius:50%;background:#f59e0b;flex-shrink:0;animation:hgDotBlink 1s ease-in-out infinite;box-shadow:0 0 6px rgba(245,158,11,0.5)}
@keyframes hgDotBlink{0%,100%{opacity:1;box-shadow:0 0 6px rgba(245,158,11,0.5)}50%{opacity:0.3;box-shadow:0 0 2px rgba(245,158,11,0.2)}}
/* ── Error dot — settled failure state, static red with a soft glow (no pulse: the turn is over) ── */
.conv-error-dot{width:8px;height:8px;border-radius:50%;background:#ef4444;flex-shrink:0;box-shadow:0 0 5px rgba(239,68,68,0.5);animation:errDotFadeIn .3s ease}
@keyframes errDotFadeIn{from{opacity:0;transform:scale(0.6)}to{opacity:1;transform:scale(1)}}
/* ── Incomplete dot — settled interrupted/unfinished turn, static amber with a soft glow (no pulse: the turn is over, just needs attention) ── */
.conv-incomplete-dot{width:8px;height:8px;border-radius:50%;background:#f59e0b;flex-shrink:0;box-shadow:0 0 5px rgba(245,158,11,0.5);animation:errDotFadeIn .3s ease}
