.translate-loading-head{display:flex;align-items:center;gap:8px;padding:9px 13px}
.translate-loading.has-preview .translate-loading-head{border-bottom:1px solid var(--accent-subtle)}
.translate-loading-label{font-size:12px;font-weight:600;letter-spacing:.02em;color:var(--accent);background:linear-gradient(90deg,var(--accent) 0%,var(--text-secondary) 50%,var(--accent) 100%);background-size:200% 100%;-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;animation:translate-shimmer 2.4s linear infinite}
