/* ── Sidebar library — book spines feel ── */
[data-theme="tofu"] .paper-sidebar-current{
  background:linear-gradient(135deg,#F0E9D4,#E8DEC5);
  border-bottom:var(--stitch)
}
[data-theme="tofu"] .paper-sidebar-title{color:#3A2F20;font-weight:700}
[data-theme="tofu"] .paper-sidebar-pages{
  font-family:var(--sans-body);color:#9B8C6E
}
[data-theme="tofu"] .paper-sidebar-lib-header{
  font-family:var(--sans-body);color:#9B8C6E
}
[data-theme="tofu"] .paper-lib-item{
  border:1.5px solid transparent;
  transition:all .12s
}
[data-theme="tofu"] .paper-lib-item:hover{
