}
[data-theme="tofu"] .paper-lib-item-title{color:#4A4233}
[data-theme="tofu"] .paper-lib-item.active .paper-lib-item-title{color:#3A2F20}
[data-theme="tofu"] .paper-lib-item-meta{
  font-family:var(--sans-body);font-size:10px;color:#9B8C6E
}

/* ── Selection toolbar — rounded pixel pill ── */
[data-theme="tofu"] .paper-selection-bar{
