.fc-icon.fc-written{color:#a78bfa;background:rgba(167,139,250,0.12)}
.fc-icon.fc-fail{color:#f87171;background:rgba(248,113,113,0.12)}
.fc-path{min-width:0;flex:1;white-space:normal;overflow-wrap:anywhere;word-break:break-word}
