/* ── File Changes: Undo actions bar ── */
.fc-actions{display:flex;align-items:center;gap:4px;margin-left:auto}
.fc-undo-btn,.fc-undo-all-btn{display:inline-flex;align-items:center;gap:3px;padding:2px 8px;border:1px solid transparent;border-radius:6px;font-size:10px;font-weight:600;font-family:'JetBrains Mono',monospace;letter-spacing:.02em;cursor:pointer;transition:all .2s ease;line-height:1.3;white-space:nowrap;background:transparent}
.fc-undo-btn{color:rgba(96,165,250,0.85);border-color:rgba(96,165,250,0.25)}
.fc-undo-btn:hover{color:#60a5fa;background:rgba(96,165,250,0.1);border-color:rgba(96,165,250,0.45);box-shadow:0 0 8px rgba(96,165,250,0.12)}
