/* ── Network-latency signal indicator ──
   Lives INSIDE .topbar-tools, so it mirrors the .topbar-tool-btn shell
   (height/radius/border/typography) for a consistent control group; only the
   signal-bars + ms readout carry the semantic state colour. */
.net-latency-badge{display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 10px;border:1px solid transparent;border-radius:8px;background:none;color:var(--text-secondary);font-family:'Jakarta Toolbar','Plus Jakarta Sans','Jakarta Fallback',sans-serif;font-size:12.5px;font-weight:600;line-height:1;white-space:nowrap;flex-shrink:0;user-select:none;cursor:default;transition:color .15s ease,background-color .15s ease,border-color .15s ease}
.net-latency-badge:hover{color:var(--text-primary);background:var(--bg-hover);border-color:var(--border-light)}
.net-latency-badge .net-bars{display:inline-flex;align-items:flex-end;gap:2px;height:14px}
.net-latency-badge .net-bar{width:3px;border-radius:1px;background:currentColor;opacity:0.25;transition:background .2s ease,opacity .2s ease}
.net-latency-badge .net-bar:nth-child(1){height:5px}
.net-latency-badge .net-bar:nth-child(2){height:8px}
.net-latency-badge .net-bar:nth-child(3){height:11px}
.net-latency-badge .net-bar:nth-child(4){height:14px}
.net-latency-badge .net-bar.lit{opacity:1}
.net-latency-badge .net-ms{min-width:36px;text-align:right;font-variant-numeric:tabular-nums;font-size:11px;letter-spacing:-0.2px;color:var(--text-tertiary)}
/* State-driven colour of the lit bars + label (the semantic signal). */
.net-latency-badge[data-state="good"] .net-bar.lit{background:#34d399}
.net-latency-badge[data-state="good"] .net-ms{color:#34d399}
.net-latency-badge[data-state="ok"] .net-bar.lit{background:#eab308}
.net-latency-badge[data-state="ok"] .net-ms{color:#eab308}
.net-latency-badge[data-state="poor"] .net-bar.lit{background:#f97316}
.net-latency-badge[data-state="poor"] .net-ms{color:#f97316}
.net-latency-badge[data-state="timeout"] .net-bar.lit{background:#ef4444}
.net-latency-badge[data-state="timeout"] .net-ms{color:#ef4444}
.net-latency-badge[data-state="offline"]{opacity:0.65}
.net-latency-badge[data-state="offline"] .net-ms{color:var(--text-tertiary)}
/* Narrow viewports: match the tool buttons' tighter padding. */
@media (max-width:1080px){.net-latency-badge{padding:0 7px}}
/* ── Timer Watcher badge & panel ── */
.timer-trigger{position:relative;user-select:none;-webkit-user-select:none}
.timer-panel{user-select:text;-webkit-user-select:text}
.timer-trigger .tm-dot{width:6px;height:6px;border-radius:50%;background:#D9A12E;animation:pulse 2s ease infinite;flex-shrink:0}
.timer-trigger .timer-count{font-size:9px;background:var(--accent);color:#fff;border-radius:9px;min-width:16px;height:16px;padding:0 4px;display:inline-flex;align-items:center;justify-content:center;font-weight:800;line-height:1}
.timer-panel{position:absolute;top:100%;right:0;margin-top:8px;width:380px;max-width:calc(100vw - 32px);max-height:460px;overflow-y:auto;background:var(--bg-secondary);border:1px solid var(--border);border-radius:var(--radius-md,10px);box-shadow:var(--clay-lg,0 8px 32px rgba(0,0,0,0.4));z-index:1000;padding:12px;display:none;white-space:normal;text-align:left;cursor:default;font-size:12px;font-family:'Plus Jakarta Sans',-apple-system,sans-serif}
.timer-panel.visible{display:block}
/* The panel is a DOM child of the badge, so hovering it propagates :hover to
   the badge. The hover-lift transform (tofu theme) spawns a new stacking
   context and re-orders the panel under the cursor → hover toggles off →
   flicker loop that also steals clicks from the panel's buttons. While the
   panel is open, pin a stable high stacking context and drop the lift. */
.timer-trigger:has(.timer-panel.visible){z-index:1001}
.timer-trigger:has(.timer-panel.visible):hover{transform:none}
.timer-panel-title{display:flex;align-items:center;gap:6px;font-size:11px;font-weight:700;color:var(--text-secondary);text-transform:uppercase;letter-spacing:0.6px;margin-bottom:10px;padding-bottom:8px;border-bottom:1px solid var(--border)}
.timer-panel-empty{color:var(--text-secondary);text-align:center;padding:24px 12px;font-size:12px;line-height:1.5}
.timer-panel-item{padding:10px;border-radius:8px;margin-bottom:8px;background:var(--bg-primary);border:1px solid var(--border);border-left:3px solid var(--text-tertiary)}
.timer-panel-item:last-child{margin-bottom:0}
.timer-panel-item.timer-status-active{border-left-color:var(--accent)}
.timer-panel-item.timer-status-triggered{border-left-color:#D9A12E}
.timer-panel-item.timer-status-cancelled{border-left-color:#C2705F}
.timer-panel-item.timer-status-exhausted{border-left-color:var(--text-tertiary)}
.timer-panel-item .tpi-header{display:flex;align-items:center;gap:7px;margin-bottom:7px}
.timer-panel-item .tpi-header-jump{cursor:pointer;border-radius:6px;margin:-3px -4px 4px;padding:3px 4px;transition:background .15s}
.timer-panel-item .tpi-header-jump:hover{background:var(--bg-hover)}
/* ── Timer poll-log modal ── */
