}
.log-clean-btn.dismiss {
  background: transparent;
  border-color: transparent;
  color: var(--text-tertiary);
  padding: 5px 6px;
}
.log-clean-btn.dismiss:hover {
  color: var(--text-secondary);
  background: var(--bg-hover);
}
/* Log clean compare preview */
.log-clean-compare {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.log-clean-section {
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  overflow: hidden;
}
.log-clean-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  background: var(--bg-tertiary);
  border-bottom: 1px solid var(--border);
}
.log-clean-section-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
}
.log-clean-section-meta {
  font-size: 10px;
  color: var(--text-tertiary);
  font-family: 'JetBrains Mono', monospace;
}
.log-clean-code {
  padding: 12px;
  margin: 0;
  background: var(--bg-primary);
  color: var(--text-secondary);
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-all;
  max-height: 300px;
  overflow-y: auto;
}

