  color:var(--text-secondary);
  border:none;
  border-radius:var(--radius-xs)
}
[data-theme="tofu"] .attach-btn:hover{
  color:var(--text-primary);
  background:var(--bg-hover)
}
[data-theme="tofu"] .attach-btn:active{
  transform:scale(.94)
}
/* Stop btn — calm solid, gentle pulse */
[data-theme="tofu"] .send-btn.stop-btn{
  background:var(--error-text);
  border:1px solid transparent;
  box-shadow:var(--clay-sm);
  animation:tofuPixelPulse 1.8s ease-in-out infinite
}
[data-theme="tofu"] .send-btn.stop-btn:hover{
  background:#9E4E3E;
  box-shadow:var(--clay-md)
}
[data-theme="tofu"] .send-btn.stop-btn:active{
  transform:none;
  box-shadow:var(--clay-pressed);
  animation:none
}
/* Gentle pulse for stop */
@keyframes tofuPixelPulse{
  0%,100%{opacity:1}
  50%{opacity:0.82}
}

