/* ══════════════════════════════════════════════════════════════
   Tofu Code Block — clean editorial code surface
   (mono kept for actual code text; cartridge frame/scanline/bevel gone)
   ══════════════════════════════════════════════════════════════ */

/* --- Code card shell --- */
[data-theme="tofu"] .md-content pre{
  position: relative;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--clay-sm);
  overflow: hidden;
  background: var(--bg-tertiary);
  margin: 18px 0;
  transition: box-shadow 0.2s ease;
}
[data-theme="tofu"] .md-content pre:hover{
  transform: none;
  box-shadow: var(--clay-md);
}

/* --- Header: quiet flat bar --- */
[data-theme="tofu"] .code-header{
  position: relative;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  border-radius: var(--radius) var(--radius) 0 0;
  padding: 6px 14px;
  color: var(--text-tertiary);
  font-family: var(--sans-body);
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: none;
}
/* (retired) pixel notch dots */
[data-theme="tofu"] .code-header::before{
  content: none;
  display: none;
}
/* lang label — mono is fine (it names a code language) */
[data-theme="tofu"] .code-header span{
  margin-left: 0;
  font-family:var(--sans-body);
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0;
}

/* --- Code content: flat surface, mono code text (no scanline) --- */
[data-theme="tofu"] .md-content pre code{
  background: var(--bg-tertiary);
  border-radius: 0 0 var(--radius) var(--radius);
  padding: 16px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 13px;
  line-height: 1.6;
}

/* --- Copy / collapse buttons — quiet ghost chips --- */
[data-theme="tofu"] .code-header .copy-btn,
[data-theme="tofu"] .code-header .code-collapse-btn{
  font-family: var(--sans-body);
  font-size: 11px;
  font-weight: 500;
  color: var(--text-secondary);
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--radius-xs);
  padding: 2px 10px;
  box-shadow: none;
  transition: background 0.18s ease, color 0.18s ease, border-color 0.18s ease;
  cursor: pointer;
  text-transform: none;
  letter-spacing: 0;
}
[data-theme="tofu"] .code-header .copy-btn:hover,
[data-theme="tofu"] .code-header .code-collapse-btn:hover{
  background: var(--bg-hover);
  color: var(--text-primary);
  border-color: var(--border);
}
[data-theme="tofu"] .code-header .copy-btn:active,
[data-theme="tofu"] .code-header .code-collapse-btn:active{
  transform: none;
  box-shadow: var(--clay-pressed);
}

/* --- Collapsed fade --- */
[data-theme="tofu"] pre.code-long[data-collapsed="true"]::after{
  background: linear-gradient(to bottom, transparent, var(--bg-tertiary));
  border-radius: 0 0 var(--radius) var(--radius);
}

/* --- Apply button — hidden in tofu theme --- */
[data-theme="tofu"] .code-header .apply-btn{
