}

/* ── Table — pixel borders ── */
[data-theme="tofu"] .md-table-wrapper{border-radius:0;border:1px solid #D8D1C0}
[data-theme="tofu"] .table-header{background:#E6E1D4;border-bottom:1px solid #D8D1C0;border-radius:0;color:#8A7458}
[data-theme="tofu"] .table-header .copy-btn{color:#8A7458}
[data-theme="tofu"] .table-header .copy-btn:hover{color:#4A4233;background:rgba(196,149,106,0.12)}
[data-theme="tofu"] .md-content table{
