  margin:0 5px;
  flex-shrink:0
}

/* ── Thinking depth bar — pixel inset capsule strip ── */
[data-theme="tofu"] .thinking-depth-bar{
  background:#E8E5DA;
  border:1.5px solid #C2BCA4;
  border-top-color:#A89878;
  border-left-color:#A89878;
  border-right-color:#FFFCF6;
  border-bottom-color:#FFFCF6;
  border-radius:4px;
  box-shadow:inset 0 1px 3px rgba(74,63,47,0.08);
  padding:2px 3px;
  gap:2px
}
[data-theme="tofu"] .depth-btn{
  font-family:var(--sans-body);
  font-weight:600;
  font-size:11px;
  color:var(--text-secondary);
  background:transparent;
  border-radius:var(--radius-xs);
  padding:2px 9px;
  letter-spacing:0;
  -webkit-font-smoothing:antialiased;
  -moz-osx-font-smoothing:grayscale;
  transition:color 0.15s,background 0.15s,box-shadow 0.15s
}
[data-theme="tofu"] .depth-btn:hover{
  color:#2A2018;
  background:rgba(196,149,106,0.1)
}
[data-theme="tofu"] .depth-btn.active{
  background:rgba(196,149,106,0.22);
  color:#2A1E10;
  box-shadow:inset 0 1px 2px rgba(0,0,0,0.1);
  border-radius:3px;
  font-weight:800
}
[data-theme="tofu"] .depth-btn[data-depth="off"].active{
  background:rgba(196,149,106,0.08);
  color:#5C4A33;
  box-shadow:none
}

/* ── Model selector — quiet token pill ── */
[data-theme="tofu"] .preset-toggle{
  border-radius:var(--radius-xs);
  /* Item 2 — frosted-glass kinship with the project bar's pills: translucent
     tofu-cream fill + backdrop blur so the toolbar reads as the SAME surface as
     the bar (the scene wash shows through between pills). */
  background:linear-gradient(180deg, rgba(250,248,242,0.62) 0%, rgba(240,237,228,0.5) 100%);
  -webkit-backdrop-filter:blur(6px) saturate(1.05);
  backdrop-filter:blur(6px) saturate(1.05);
  border:1px solid var(--border);
  color:var(--text-secondary);
  box-shadow:none;
  clip-path:none;
  image-rendering:auto;
  transition:background 0.18s ease,color 0.18s ease,border-color 0.18s ease
}
[data-theme="tofu"] .preset-toggle:hover{
  background:var(--bg-hover);
  color:var(--text-primary);
  box-shadow:none;
  transform:none
}
[data-theme="tofu"] .preset-toggle:active{
  transform:none;
  box-shadow:var(--clay-pressed)
}
/* Brand color overrides — slim colored bottom accent */
[data-theme="tofu"] .preset-toggle[data-brand="claude"]{color:#9A6520;box-shadow:inset 0 -2px 0 rgba(217,119,6,0.35)}
[data-theme="tofu"] .preset-toggle[data-brand="openai"]{color:#2D7A4A;box-shadow:inset 0 -2px 0 rgba(16,163,127,0.3)}
[data-theme="tofu"] .preset-toggle[data-brand="gemini"]{color:#3A6898;box-shadow:inset 0 -2px 0 rgba(66,133,244,0.3)}
[data-theme="tofu"] .preset-toggle[data-brand="deepseek"]{color:#4A5A92;box-shadow:0 2px 0 rgba(154,144,122,0.4), inset 0 -2px 0 rgba(77,107,254,0.3)}
[data-theme="tofu"] .preset-toggle .ps-label{
