}
[data-theme="tofu"] .ps-dd-depth-wrap{background:#F4F2EB;border-top-color:#C2BCA4}
[data-theme="tofu"] .ps-dd-hint{border-top-color:#C2BCA4;color:#8A7A5A}
[data-theme="tofu"] .ps-dd-hint:hover{color:#5C4A33}
[data-theme="tofu"] .preset-dropdown-item{
  border-radius:2px;
  font-family:var(--sans-body);
  font-size:11px;
