  border: 1px solid rgba(106,138,94,0.25);
  border-radius:var(--radius-sm);
  box-shadow:var(--clay-sm);
  animation: tofuStamp 0.4s cubic-bezier(0.34,1.56,0.64,1) both;
}

/* Error: pixel azuki chip */
[data-theme="tofu"] .ptool-badge-err{
  color: #A85A4A;
