}

/* ── Spinner — warm kinako ── */
[data-theme="tofu"] .ptool-spinner{
  border-color: rgba(196,149,106,0.2);
  border-top-color: #C4956A;
}

/* ── Search orbit dots — warm palette ── */
[data-theme="tofu"] .ptool-panel .search-orbit-center{ background: #C4956A; }
