/* ═══════════════════════════════════════════════════════════
   ★ Tofu "Washi Terminal" — run_command block v3
   Inspired by: washi paper texture + retro warm CRT +
   traffic-light header dots + blinking cursor + typewriter
   feel. Desaturated to match refined tofu palette.
   ═══════════════════════════════════════════════════════════ */

/* Flat content inside the .ptool-turn cream card — NO nested card chrome
 * (no own border/radius/shadow/parchment bg). The .ptool-turn shell is the
 * one and only card; this block just supplies the terminal character (dot,
 * recessed $ tray, dashed fold line). See docs: run_command double-box fix. */
[data-theme="tofu"] .ptool-cmd-block{
  --_rail: #B0936E;
  --_rail-glow: transparent;
  --_dot-color: #B0936E;
  position: relative;
  border: none;
  border-radius: 0;
  background: none;
  box-shadow: none;
  overflow: hidden;
}

/* ── Header: traffic-light dots + label + status ── */
[data-theme="tofu"] .ptool-cmd-header{
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  background: linear-gradient(180deg, rgba(0,0,0,0.015) 0%, transparent 100%);
  border-bottom: 1px solid rgba(178,163,140,0.2);
  z-index: 1;
}
/* traffic light dot — sits in the icon area, color changes with state */
[data-theme="tofu"] .ptool-cmd-icon{
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 16px; height: 16px;
  flex-shrink: 0;
}
[data-theme="tofu"] .ptool-cmd-icon::before{
  content: "";
  position: absolute;
  left: 50%; top: 50%;
  margin: -4px 0 0 -4px;
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--_dot-color);
  box-shadow: 0 0 0 2px rgba(255,255,255,0.5), 0 0 4px var(--_rail-glow);
  transition: background 0.4s, box-shadow 0.4s;
}
[data-theme="tofu"] .ptool-cmd-icon svg{
  opacity: 0;
  width: 0; height: 0;
}
[data-theme="tofu"] .ptool-cmd-label{
  color: #716A55;
  font-family:var(--sans-body);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  opacity: 0.75;
}
[data-theme="tofu"] .ptool-cmd-status{
  margin-left: auto;
  font-family:var(--sans-body);
  font-size: 10px;
  font-weight: 700;
  padding: 2px 10px;
  border-radius: 20px;
  letter-spacing: 0.03em;
  transition: all 0.35s cubic-bezier(0.34,1.56,0.64,1);
}

/* ═══ STATE: Running ═══ */
[data-theme="tofu"] .ptool-cmd-running{
  --_dot-color: #CCA858;
  --_rail-glow: rgba(204,168,88,0.4);
  border-color: rgba(204,168,88,0.3);
}
[data-theme="tofu"] .ptool-cmd-running .ptool-cmd-icon::before{
  animation: tofuDotPulse 1.4s ease-in-out infinite;
}
[data-theme="tofu"] .ptool-cmd-running .ptool-cmd-label{
  color: #A07D5A;
  opacity: 1;
}
/* Subtle warm scanline across the whole block while running */
[data-theme="tofu"] .ptool-cmd-running::after{
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: linear-gradient(90deg,
    transparent 0%,
    rgba(187,149,114,0.04) 40%,
    rgba(187,149,114,0.07) 50%,
    rgba(187,149,114,0.04) 60%,
    transparent 100%);
  background-size: 250% 100%;
  animation: tofuCmdSweep 3s ease-in-out infinite;
  pointer-events: none;
  z-index: 0;
}

/* ═══ STATE: OK / Success ═══ */
[data-theme="tofu"] .ptool-cmd-ok{
  --_dot-color: #6A9E5A;
  --_rail-glow: rgba(106,158,90,0.35);
  border-color: rgba(106,158,90,0.2);
}
[data-theme="tofu"] .ptool-cmd-ok .ptool-cmd-icon::before{
  animation: tofuDotStamp 0.4s cubic-bezier(0.34,1.56,0.64,1) both;
}
[data-theme="tofu"] .ptool-cmd-ok .ptool-cmd-label{
  color: #5E8A50;
  opacity: 0.85;
}
[data-theme="tofu"] .ptool-cmd-ok .ptool-cmd-status{
  color: #F4F1EA;
  background: linear-gradient(135deg, #6A9E5A 0%, #5C8A4E 100%);
  border: none;
  box-shadow: 0 1px 3px rgba(94,138,80,0.18);
  animation: tofuStamp 0.45s cubic-bezier(0.34,1.56,0.64,1) both,
             tofuStatusGlow 0.6s 0.3s ease-out both;
}

/* ═══ STATE: Error ═══ */
[data-theme="tofu"] .ptool-cmd-err{
  --_dot-color: #C0685A;
  --_rail-glow: rgba(192,104,90,0.35);
  border-color: rgba(192,104,90,0.25);
}
[data-theme="tofu"] .ptool-cmd-err .ptool-cmd-icon::before{
  animation: tofuDotStamp 0.4s cubic-bezier(0.34,1.56,0.64,1) both;
}
[data-theme="tofu"] .ptool-cmd-err .ptool-cmd-label{
  color: #A85A4A;
  opacity: 0.85;
}
[data-theme="tofu"] .ptool-cmd-err .ptool-cmd-status{
  color: #F4F1EA;
  background: linear-gradient(135deg, #C0685A 0%, #A85A4A 100%);
  border: none;
  box-shadow: 0 1px 3px rgba(184,106,90,0.18);
  animation: tofuStamp 0.45s cubic-bezier(0.34,1.56,0.64,1) both;
}

/* ═══ STATE: Timeout ═══ */
[data-theme="tofu"] .ptool-cmd-timeout,
[data-theme="tofu"] .ptool-cmd-notrun{
  --_dot-color: #CCA858;
  --_rail-glow: rgba(204,168,88,0.3);
  border-color: rgba(204,168,88,0.2);
}
[data-theme="tofu"] .ptool-cmd-notrun .ptool-cmd-status{
  color: #6B5E42;
  background: rgba(204,168,88,0.12);
}
[data-theme="tofu"] .ptool-cmd-reason{
  color: #7A6A4A;
  background: rgba(204,168,88,0.07);
  border-top: 1px dashed rgba(178,163,140,0.3);
}
[data-theme="tofu"] .ptool-cmd-timeout .ptool-cmd-label{
  color: #A07D5A;
  opacity: 0.85;
}
[data-theme="tofu"] .ptool-cmd-timeout .ptool-cmd-status{
  color: #6B5E42;
  background: rgba(204,168,88,0.12);
  border: 1px solid rgba(204,168,88,0.22);
}

/* Inline description on the header title line — tofu palette */
[data-theme="tofu"] .ptool-cmd-desc-inline{
  color: #6B5E42;
  font-family: var(--sans-body);
  font-size: 11.5px;
  opacity: 0.85;
}
/* ── Description: intent caption woven above the command (no detached band) ── */
[data-theme="tofu"] .ptool-cmd-desc{
  padding: 9px 16px 3px;
  color: #6B5E42;
  background: transparent;
  border-bottom: none;
  font-family:var(--sans-body);
  font-size: 12px;
  line-height: 1.55;
  z-index: 1;
}
[data-theme="tofu"] .ptool-cmd-desc::before{
  background: var(--_dot-color, #B0936E);
  opacity: 0.6;
}

/* ── Code tray: recessed with prompt chevron & blinking cursor ── */
[data-theme="tofu"] .ptool-cmd-code{
  position: relative;
  margin: 0;
  padding: 10px 16px 10px 16px;
  background: rgba(0,0,0,0.02);
  border-radius:var(--radius-sm);
  box-shadow:
    inset 0 1px 3px rgba(138,122,86,0.06);
  z-index: 1;
}
[data-theme="tofu"] .ptool-cmd-code code{
  font-family: 'JetBrains Mono', 'Menlo', 'SF Mono', monospace;
  color: #4A4233;
  font-size: 12px;
  letter-spacing: -0.01em;
  line-height: 1.55;
  word-break: break-all;
}
/* Blinking block cursor after command text when running */
[data-theme="tofu"] .ptool-cmd-running .ptool-cmd-code code::after{
  content: "█";
  display: inline;
  color: #A07D5A;
  font-weight: 400;
  animation: tofuCursorBlink 1s step-end infinite;
  margin-left: 1px;
}

/* ── Output area — warm paper with top fold line ── */
[data-theme="tofu"] .ptool-cmd-output-wrap{
  border-top: 1px dashed rgba(178,163,140,0.3);
  z-index: 1;
  position: relative;
}
[data-theme="tofu"] .ptool-cmd-toggle{
  color: #A07D5A;
  opacity: 0.55;
  font-family:var(--sans-body);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.02em;
  padding: 5px 16px;
  transition: opacity 0.2s, background 0.2s, color 0.2s;
  cursor: pointer;
  user-select: none;
}
[data-theme="tofu"] .ptool-cmd-toggle:hover{
  opacity: 1;
  color: #8A7458;
  background: rgba(187,149,114,0.04);
}
[data-theme="tofu"] .ptool-cmd-output{
  background: rgba(187,149,114,0.018);
  border-top: 1px solid rgba(178,163,140,0.12);
  padding: 8px 16px 10px 16px;
}
[data-theme="tofu"] .ptool-cmd-output code{
  font-family: 'JetBrains Mono', 'Menlo', 'SF Mono', monospace;
  color: #6B6252;
  font-size: 11px;
  line-height: 1.5;
}

/* ── Keyframes ── */
@keyframes tofuDotPulse{
  0%,100%{ transform: scale(1); box-shadow: 0 0 0 2px rgba(255,255,255,0.5), 0 0 4px var(--_rail-glow); }
  50%    { transform: scale(1.15); box-shadow: 0 0 0 2px rgba(255,255,255,0.5), 0 0 8px var(--_rail-glow); }
}
@keyframes tofuDotStamp{
  0%  { transform: scale(0.4); opacity: 0; }
  50% { transform: scale(1.2); opacity: 1; }
  100%{ transform: scale(1); opacity: 1; }
}
@keyframes tofuCursorBlink{
  0%,100%{ opacity: 1; }
  50%    { opacity: 0; }
}
@keyframes tofuRailPulse{
  0%,100%{ opacity: 0.7; box-shadow: 2px 0 6px rgba(187,149,114,0.1); }
  50%    { opacity: 1;   box-shadow: 3px 0 12px rgba(187,149,114,0.25); }
}
@keyframes tofuIconBreathe{
  0%,100%{ transform: scale(1); }
  50%    { transform: scale(1.08); }
}
@keyframes tofuStatusGlow{
  0%  { box-shadow: 0 1px 3px rgba(94,138,80,0.18), 0 0 0 0 rgba(94,138,80,0.28); }
  60% { box-shadow: 0 1px 3px rgba(94,138,80,0.18), 0 0 0 6px rgba(94,138,80,0); }
  100%{ box-shadow: 0 1px 3px rgba(94,138,80,0.18), 0 0 0 0 rgba(94,138,80,0); }
}

