/* ═══════════════════════════════════════════
   ★ Memory Modal — v7 Tofu Unified Design
   Matches the Settings panel "tofu block" aesthetic:
   cream bg, thick ink borders, box-shadow, gold kintsugi
   ═══════════════════════════════════════════ */

/* ── Design tokens (same as settings-panel for consistency) ── */
.memory-modal{
  --m-white:     #faf8f3;
  --m-cream:     #f2ecda;
  --m-skin:      #e4d6bf;
  --m-board:     #35302a;
  --m-board-lit: #443c32;
  --m-gold:      #c9993f;
  --m-gold-dim:  #a87d2e;
  --m-gold-glow: rgba(201,153,63,0.18);
  --m-ink:       #1a1814;
  --m-ink-soft:  #3d362c;
  --m-ink-faint: #6b6050;
  --m-done:      #4ade80;
  --m-blocked:   #f87171;
  --m-accent:    #6e56cf;
  --m-shadow:    6px 6px 0 var(--m-ink);
  --m-shadow-sm: 3px 3px 0 var(--m-ink);
  --m-shadow-xs: 2px 2px 0 var(--m-ink);
  --m-border:    2.5px solid var(--m-ink);
  --m-border-sm: 1.5px solid var(--m-ink);
  --m-radius:    0px;
}

/* ── Modal shell — tofu block ── */
.memory-modal{
  width:620px;
  max-width:95vw;
  padding:0;
  border-radius:var(--m-radius);
  display:flex;
  flex-direction:column;
  max-height:85vh;
  max-height:calc(var(--vh100,100vh)*0.85);
  overflow:hidden;
  background:var(--m-white);
  border:3px solid var(--m-ink);
  box-shadow:var(--m-shadow);
  color:var(--m-ink);
  font-family:'Inter','SF Pro',-apple-system,system-ui,sans-serif;
  animation:memorySlam .22s cubic-bezier(.2,1.2,.4,1) both;
}
@keyframes memorySlam{
  from{transform:translateY(16px) scale(.97);opacity:0}
  to{transform:none;opacity:1}
}

/* Override base .modal input/select bleed */
.memory-modal input,
.memory-modal select,
.memory-modal textarea{
  margin:0;padding:0;font-family:inherit;border:none;background:none;color:var(--m-ink);
}

/* ── Header — thick bottom border with gold kintsugi line ── */
.memory-modal-header{
  padding:18px 22px 14px;
  border-bottom:3px solid var(--m-ink);
  background:var(--m-cream);
  flex-shrink:0;
  position:relative;
}
/* Gold kintsugi line under header */
.memory-modal-header::after{
  content:'';
  position:absolute;
  bottom:-2px;left:0;right:0;height:2px;
  background:linear-gradient(90deg,transparent 0%,var(--m-gold) 15%,var(--m-gold) 50%,var(--m-gold-dim) 85%,transparent 100%);
  opacity:.55;
}
.memory-modal-title{
  margin:0 0 2px;
  font-size:18px;font-weight:900;
  color:var(--m-ink);
  letter-spacing:-.02em;
  text-transform:uppercase;
}
.memory-modal-subtitle{
  font-size:11px;color:var(--m-ink-faint);line-height:1.4;font-weight:500;
}
.memory-modal-close{
  position:absolute;top:14px;right:14px;
  width:30px;height:30px;
  background:var(--m-white);
  border:var(--m-border-sm);
  box-shadow:var(--m-shadow-xs);
  color:var(--m-ink);cursor:pointer;
  padding:0;border-radius:var(--m-radius);
  display:flex;align-items:center;justify-content:center;
  transition:transform .1s,box-shadow .1s,background .1s;
}
.memory-modal-close:hover{
  transform:translate(1px,1px);
  box-shadow:1px 1px 0 var(--m-ink);
  background:var(--m-blocked);color:var(--m-white);
}
.memory-modal-status{
  padding:4px 22px 0;font-size:11px;color:var(--m-gold-dim);min-height:0;font-weight:600;
}

/* ── Stats — tofu chips with ink borders ── */
.memory-stats{
  display:flex;align-items:center;justify-content:center;
  gap:8px;padding:12px 22px;
  border-bottom:2px dashed var(--m-ink-soft);
  background:var(--m-white);
  flex-shrink:0;
}
.memory-stat{
  display:flex;align-items:baseline;gap:4px;
  padding:4px 12px;
  background:var(--m-cream);
  border:var(--m-border-sm);
  box-shadow:var(--m-shadow-xs);
}
.memory-stat + .memory-stat{
  border-left:var(--m-border-sm);
}
.memory-stat-num{
  font-size:15px;font-weight:900;
  color:var(--m-ink);
  line-height:1;font-variant-numeric:tabular-nums;
}
.memory-stat-num.memory-stat-active{color:#16a34a}
.memory-stat-label{
  font-size:10px;color:var(--m-ink-soft);font-weight:700;
  text-transform:uppercase;letter-spacing:.04em;
}
.memory-stat-divider{display:none}

/* ── Toolbar: tabs + search ── */
.memory-toolbar{
  padding:10px 22px;
  display:flex;align-items:center;gap:10px;
  border-bottom:1.5px solid rgba(26,24,20,0.1);
  background:var(--m-white);
  flex-shrink:0;
}
.memory-tabs{
  display:flex;gap:0;
  flex-shrink:0;
}
.memory-tab{
  padding:5px 14px;
  border:var(--m-border-sm);
  background:var(--m-white);
  color:var(--m-ink-soft);
  font-size:11px;font-weight:700;
  cursor:pointer;transition:background .15s,color .15s;
  white-space:nowrap;line-height:1.4;
  text-transform:uppercase;letter-spacing:.03em;
}
.memory-tab + .memory-tab{border-left:none}
.memory-tab.active{
  background:var(--m-gold);color:var(--m-ink);
  box-shadow:inset 0 -2px 0 var(--m-gold-dim);
}
.memory-tab:hover:not(.active){background:var(--m-cream)}
.memory-search-box{
  flex:1;position:relative;min-width:0;max-width:200px;
}
.memory-modal .memory-search-input{
  display:block;
  width:100%;
  height:30px;
  padding:0 10px 0 28px;
  border:var(--m-border-sm);
  background:var(--m-white);
  color:var(--m-ink);
  font-size:12px;font-weight:500;
  line-height:30px;
  outline:none;
  transition:border-color .15s,box-shadow .15s;
  box-sizing:border-box;
  border-radius:0;
}
.memory-modal .memory-search-input:focus{
  border-color:var(--m-gold);
  box-shadow:0 0 0 2px var(--m-gold-glow);
}
.memory-modal .memory-search-input::placeholder{
  color:var(--m-ink-faint);font-weight:500;
}
.memory-search-icon{
  position:absolute;left:8px;top:50%;transform:translateY(-50%);
  color:var(--m-ink-faint);pointer-events:none;
}

/* ── List container — stable scrollbar ── */
.memory-list{
  flex:1;
  overflow-y:scroll;
  padding:12px 22px;
  display:flex;flex-direction:column;gap:6px;
  min-height:100px;
  isolation:isolate;
  background:linear-gradient(180deg,var(--m-white) 0%,#f5f2ea 100%);
}
@supports(scrollbar-gutter:stable){
  .memory-list{overflow-y:auto;scrollbar-gutter:stable}
}
.memory-list::-webkit-scrollbar{width:5px}
.memory-list::-webkit-scrollbar-track{background:transparent}
.memory-list::-webkit-scrollbar-thumb{background:var(--m-skin);border-radius:0}
.memory-list::-webkit-scrollbar-thumb:hover{background:var(--m-board-lit)}

/* ── Loading ── */
.memory-loading{
  padding:32px 20px;display:flex;align-items:center;justify-content:center;gap:6px;
  color:var(--m-ink-soft);font-size:12px;font-weight:600;
}
.memory-loading-dot{
  width:6px;height:6px;border-radius:0;
  background:var(--m-gold);
  animation:memoryDotPulse .8s ease-in-out infinite alternate;
}
.memory-loading-dot:nth-child(2){animation-delay:.15s}
.memory-loading-dot:nth-child(3){animation-delay:.3s}
@keyframes memoryDotPulse{from{opacity:.3}to{opacity:1}}

/* ── Skeleton ── */
.memory-skeleton{
  height:52px;
  background:linear-gradient(90deg,var(--m-cream) 25%,var(--m-skin) 50%,var(--m-cream) 75%);
  background-size:200% 100%;animation:skeletonShimmer 1.5s ease-in-out infinite;
  border:1px solid rgba(26,24,20,0.08);
}
@keyframes skeletonShimmer{0%{background-position:200% 0}100%{background-position:-200% 0}}

/* ── Empty / Error ── */
.memory-empty{text-align:center;padding:40px 20px;color:var(--m-ink-soft)}
.memory-empty-icon{margin-bottom:8px;display:block}
.memory-empty-icon svg{opacity:.35;stroke:var(--m-ink-soft)}
.memory-empty-title{font-size:13px;font-weight:800;color:var(--m-ink);margin-bottom:4px;text-transform:uppercase;letter-spacing:.03em}
.memory-empty-hint{font-size:11px;color:var(--m-ink-faint);margin-top:4px;line-height:1.7}
.memory-card-error{text-align:center;padding:20px;color:var(--m-blocked);font-size:12px;font-weight:600;background:rgba(248,113,113,0.06);border:1px solid rgba(248,113,113,0.15)}
.memory-retry-btn{
  margin-top:10px;padding:5px 14px;
  border:var(--m-border-sm);
  background:var(--m-white);color:var(--m-ink);
  font-size:11px;font-weight:700;cursor:pointer;
  box-shadow:var(--m-shadow-xs);
  transition:transform .1s,box-shadow .1s,background .1s;
}
.memory-retry-btn:hover{
  transform:translate(1px,1px);
  box-shadow:1px 1px 0 var(--m-ink);
  background:var(--m-cream);
}

/* ═══════════════════════════════════════════
   Memory Card — tofu block card style
   ═══════════════════════════════════════════ */
.memory-card{
  background:var(--m-white);
  border:1.5px solid var(--m-ink);
  box-shadow:2px 2px 0 rgba(26,24,20,0.12);
  transition:background .15s,box-shadow .15s;
}
.memory-card:hover{
  background:var(--m-cream);
  box-shadow:3px 3px 0 rgba(26,24,20,0.18);
}
.memory-card.is-disabled{opacity:.4}

/* Header: [expand 16px] [10px gap] [name flex] [scope] [toggle] [delete] */
.memory-card-header{
  display:flex;align-items:center;gap:10px;
  padding:9px 12px;
  cursor:pointer;user-select:none;
}

/* Expand chevron */
.memory-card-expand-icon{
  width:16px;height:16px;flex-shrink:0;
  display:inline-flex;align-items:center;justify-content:center;
  color:var(--m-ink-faint);
  transition:transform .2s ease,color .2s;
}
.memory-card-expand-icon.expanded{
  transform:rotate(90deg);color:var(--m-ink);
}

/* Name */
.memory-card-name{
  flex:1;min-width:0;
  font-size:12px;font-weight:700;color:var(--m-ink);
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;line-height:1.4;
  letter-spacing:-.01em;
}

/* Scope badge — tofu style */
.memory-card-scope{
  font-size:9px;padding:2px 8px;
  font-weight:800;letter-spacing:.05em;flex-shrink:0;line-height:1.4;
  text-transform:uppercase;
  border:1px solid var(--m-ink);
}
.memory-card-scope.project{background:rgba(110,86,207,0.1);color:#5b3fb5}
.memory-card-scope.global{background:rgba(34,197,94,0.1);color:#147a3e}

/* Actions container */
.memory-card-actions{display:flex;gap:4px;align-items:center;flex-shrink:0}

/* Toggle switch — tofu style */
.memory-toggle-switch{display:inline-flex;align-items:center;cursor:pointer;flex-shrink:0}
.memory-toggle-track{
  width:30px;height:16px;
  background:var(--m-skin);
  border:1px solid var(--m-ink);
  position:relative;
  transition:background .25s;
}
.memory-toggle-thumb{
  position:absolute;top:2px;left:2px;
  width:10px;height:10px;
  background:var(--m-ink-faint);
  transition:left .25s,background .25s;
}
.memory-toggle-switch.on .memory-toggle-track{background:rgba(74,222,128,0.35);border-color:var(--m-ink)}
.memory-toggle-switch.on .memory-toggle-thumb{left:16px;background:#16a34a}

/* Delete */
.memory-delete-btn{
  background:none;border:none;cursor:pointer;
  padding:2px;
  color:var(--m-ink-faint);opacity:.3;
  transition:opacity .15s,color .15s;
  display:inline-flex;align-items:center;justify-content:center;
  width:20px;height:20px;flex-shrink:0;
}
.memory-delete-btn:hover{opacity:1;color:var(--m-blocked)}

/*
 * Sub-header content left-padding = 12px pad + 16px icon + 10px gap = 38px
 */

/* Description */
.memory-card-desc{
  font-size:11px;color:var(--m-ink-faint);line-height:1.5;
  padding:0 12px 6px 38px;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;
  overflow:hidden;word-break:break-word;
}

/* Tags */
.memory-card-tags{display:flex;gap:3px;flex-wrap:wrap;padding:0 12px 8px 38px}
.memory-card-tag{
  font-size:9px;padding:1px 6px;
  border:1px solid rgba(26,24,20,0.15);
  background:var(--m-cream);color:var(--m-ink-soft);
  white-space:nowrap;font-family:'JetBrains Mono','SF Mono',Monaco,Consolas,monospace;
  font-weight:600;
}

/* ── Body — expanded content ── */
.memory-card-body{
  display:none;
  margin:0 12px 10px 38px;padding:10px 12px;
  background:rgba(26,24,20,0.03);
  border:1px solid rgba(26,24,20,0.1);
  font-size:12px;line-height:1.6;color:var(--m-ink-soft);
  word-break:break-word;
  max-height:280px;overflow-y:auto;overflow-x:hidden;
}
.memory-card-body.open{
  display:block;
  animation:memoryBodyFadeIn .15s ease-out;
}
@keyframes memoryBodyFadeIn{from{opacity:0}to{opacity:1}}
.memory-card-body::-webkit-scrollbar{width:3px}
.memory-card-body::-webkit-scrollbar-thumb{background:var(--m-skin);border-radius:0}

/* Body inner markdown */
.memory-card-body-inner{line-height:1.6;overflow-wrap:break-word;color:var(--m-ink-soft)}
.memory-card-body-inner h1,.memory-card-body-inner h2,.memory-card-body-inner h3{color:var(--m-ink);margin:10px 0 5px;font-size:13px;font-weight:800}
.memory-card-body-inner h1{font-size:15px}
.memory-card-body-inner h2{font-size:14px}
.memory-card-body-inner p{margin:5px 0}
.memory-card-body-inner ul,.memory-card-body-inner ol{margin:5px 0;padding-left:18px}
.memory-card-body-inner li{margin:2px 0}
.memory-card-body-inner code{font-family:'JetBrains Mono','SF Mono',Monaco,Consolas,monospace;font-size:11px;background:rgba(26,24,20,0.06);padding:1px 5px;border:1px solid rgba(26,24,20,0.08)}
.memory-card-body-inner pre{background:rgba(26,24,20,0.04);border:1px solid rgba(26,24,20,0.08);padding:10px;overflow-x:auto;margin:6px 0;max-width:100%}
.memory-card-body-inner pre code{background:none;padding:0;font-size:11px;line-height:1.5;border:none}
.memory-card-body-inner blockquote{border-left:3px solid var(--m-gold);padding-left:10px;margin:6px 0;color:var(--m-ink-faint)}
.memory-card-body-inner a{color:var(--m-accent);text-decoration:underline}

/* ── Add-memory form ── */
.memory-add-section{
  padding:14px 14px;
  background:var(--m-cream);
  border:1.5px solid var(--m-ink);
  box-shadow:var(--m-shadow-xs);
  margin:0 22px 10px;flex-shrink:0;
}
.memory-add-header{
  margin:0 0 10px;font-size:11px;font-weight:800;color:var(--m-ink);
  display:flex;align-items:center;gap:6px;
  text-transform:uppercase;letter-spacing:.04em;
}
.memory-modal .memory-input{
  display:block;width:100%;padding:7px 10px;
  border:var(--m-border-sm);
  background:var(--m-white);
  color:var(--m-ink);font-size:12px;margin-bottom:6px;
  outline:none;box-sizing:border-box;transition:border-color .15s,box-shadow .15s;
  border-radius:0;
}
.memory-modal .memory-input:focus{border-color:var(--m-gold);box-shadow:0 0 0 2px var(--m-gold-glow)}
.memory-modal .memory-textarea{
  display:block;width:100%;padding:7px 10px;
  border:var(--m-border-sm);
  background:var(--m-white);
  color:var(--m-ink);font-size:12px;
  font-family:'JetBrains Mono',monospace;margin-bottom:6px;
  outline:none;resize:vertical;box-sizing:border-box;
  transition:border-color .15s,box-shadow .15s;min-height:72px;
  border-radius:0;
}
.memory-modal .memory-textarea:focus{border-color:var(--m-gold);box-shadow:0 0 0 2px var(--m-gold-glow)}
.memory-modal .memory-select{
  padding:7px 10px;
  border:var(--m-border-sm);
  background:var(--m-white);
  color:var(--m-ink);font-size:12px;
  outline:none;transition:border-color .15s;
  border-radius:0;
}
.memory-modal .memory-select:focus{border-color:var(--m-gold)}
.memory-field-label{
  display:block;margin:2px 0 4px;font-size:11px;font-weight:700;
  color:var(--m-ink);letter-spacing:.02em;
}
.memory-field-hint{
  margin:0 0 8px;font-size:10.5px;line-height:1.5;color:var(--m-ink-faint);
}
.memory-add-row{display:flex;gap:6px;align-items:center}
.btn-sm{padding:7px 16px !important;font-size:12px !important;border-radius:0 !important}
#memoryToggle.active{background:rgba(201,153,63,0.15);color:#a87d2e;border-color:rgba(201,153,63,0.3)}

/* ── Modal footer — tofu block actions ── */
.memory-modal-footer{
  padding:12px 22px;
  border-top:2px solid var(--m-ink);
  background:var(--m-cream);
  display:flex;align-items:center;gap:8px;flex-shrink:0;
  position:relative;
}
/* Gold kintsugi line above footer */
.memory-modal-footer::before{
  content:'';position:absolute;
  top:-1px;left:0;right:0;height:1px;
  background:linear-gradient(90deg,transparent 0%,var(--m-gold) 20%,var(--m-gold-dim) 80%,transparent 100%);
  opacity:.45;
}
.memory-action-btn{
  padding:6px 14px;
  border:var(--m-border-sm);
  font-size:11px;font-weight:700;cursor:pointer;
  box-shadow:var(--m-shadow-xs);
  transition:transform .1s,box-shadow .1s,background .1s;
  display:inline-flex;align-items:center;gap:5px;
  text-transform:uppercase;letter-spacing:.02em;
  background:var(--m-white);color:var(--m-ink);
}
.memory-action-btn:hover{
  transform:translate(1px,1px);
  box-shadow:1px 1px 0 var(--m-ink);
}
.memory-btn-close{background:var(--m-white);color:var(--m-ink-soft)}
.memory-btn-close:hover{background:var(--m-cream)}
.memory-btn-on{background:var(--m-gold);color:var(--m-ink)}
.memory-btn-on:hover{background:var(--m-gold-dim);transform:translate(1px,1px);box-shadow:1px 1px 0 var(--m-ink)}
.memory-btn-off{background:var(--m-blocked);color:var(--m-white)}
.memory-btn-off:hover{background:#ef4444;transform:translate(1px,1px);box-shadow:1px 1px 0 var(--m-ink)}
.memory-btn-add{background:var(--m-accent);color:var(--m-white);border-color:var(--m-ink)}
.memory-btn-add:hover{background:#5b3fb5;transform:translate(1px,1px);box-shadow:1px 1px 0 var(--m-ink)}

/* ── Skill-package badge on memory cards ── */
.memory-card-pkg{display:inline-flex;align-items:center;gap:3px;padding:1px 6px;border:1px solid var(--m-ink);border-radius:3px;background:var(--m-skin);color:var(--m-ink);font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.04em}
.memory-card-pkg svg{display:block}

/* ── Skills Settings tab ── App-Store layout ── */
.skills-scope-tabs{display:inline-flex;gap:4px;margin-right:10px;padding:2px;background:var(--bg-tertiary,#1a1a1a);border:1px solid var(--border-color,#333);border-radius:6px}
.skills-scope-tab{padding:3px 12px;border:none;background:transparent;color:var(--text-secondary,#aaa);font-size:12px;border-radius:4px;cursor:pointer;transition:all .15s ease}
.skills-scope-tab:hover{color:var(--text-primary,#fff)}
.skills-scope-tab.active{background:var(--bg-secondary,#2a2a2a);color:var(--text-primary,#fff);box-shadow:0 1px 3px rgba(0,0,0,.2)}

.skills-drop-zone{display:flex;align-items:center;justify-content:center;gap:10px;padding:14px 18px;margin:8px 0 14px;border:1.5px dashed var(--border-color,#444);border-radius:8px;color:var(--text-secondary,#888);font-size:12.5px;cursor:pointer;transition:all .2s ease;background:transparent}
.skills-drop-zone:hover{border-color:var(--accent,#6c64e6);color:var(--text-primary,#ccc);background:rgba(108,100,230,.05)}
.skills-drop-zone.is-dragging{border-color:var(--accent,#6c64e6);border-style:solid;background:rgba(108,100,230,.12);color:var(--text-primary,#fff);transform:scale(1.005)}
.skills-drop-zone-text{pointer-events:none}

/* Skill card uses mcp-app-card as base; add skill-specific accents.
 * The base .mcp-app-card is a 2-col grid (44px icon | 1fr content). The
 * skill-only children (author line, requirement warning, footer) MUST be
 * pinned to the content column / full width — otherwise the grid
 * auto-places them in column 1 under the icon and the card looks broken. */
.mcp-app-card.skill-card .mcp-app-icon{filter:saturate(1.1)}
.mcp-app-card .skill-badge-official{display:inline-flex;align-items:center;gap:3px;padding:1px 6px;margin-left:6px;border:1px solid currentColor;border-radius:10px;background:transparent;color:#d97706;font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;vertical-align:middle}
.mcp-app-card .skill-badge-warn{grid-column:2;justify-self:start;display:inline-flex;align-items:center;gap:3px;padding:1px 6px;margin-top:4px;border:1px solid rgba(234,179,8,.4);border-radius:3px;background:rgba(234,179,8,.1);color:#d4a518;font-size:10px;font-weight:500}
.mcp-app-card .skill-author{grid-column:2;font-size:10px;opacity:.55;margin-top:2px}
.mcp-app-card .skill-card-footer{grid-column:1 / -1;display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:8px;padding-top:8px;min-height:30px;border-top:1px solid var(--border-color,#333)}
.mcp-app-card .skill-card-actions{display:flex;gap:4px;flex-wrap:wrap;justify-content:flex-end}

.mcp-app-card.is-installed{background:rgba(34,197,94,.05);border-color:rgba(34,197,94,.25)}
.mcp-app-card .skill-installed-tag{display:inline-flex;align-items:center;gap:3px;padding:1px 7px;border-radius:10px;background:rgba(34,197,94,.15);color:#15803d;font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.04em;align-self:center}

/* Skills file browser list */
.skills-files-modal{max-width:640px;max-height:80vh;max-height:calc(var(--vh100,100vh)*0.8);display:flex;flex-direction:column}
.skills-files-list{flex:1;overflow-y:auto;margin:12px 0;padding:8px 0;border:1px solid var(--border-color,#333);border-radius:6px;background:var(--bg-tertiary,#161616);max-height:50vh;max-height:calc(var(--vh100,100vh)*0.5)}
.skills-file-row{display:flex;align-items:center;gap:10px;padding:6px 12px;font-size:12.5px;color:var(--text-primary,#ddd);border-bottom:1px solid rgba(255,255,255,.03)}
.skills-file-row:last-child{border-bottom:none}
.skills-file-row:hover{background:rgba(255,255,255,.03)}
.skills-file-kind{flex:0 0 16px;font-size:14px;text-align:center}
.skills-file-kind svg{width:14px;height:14px;vertical-align:middle}
.skills-file-path{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-family:var(--font-mono,monospace);font-size:11.5px}
.skills-file-size{flex:0 0 auto;font-size:10px;opacity:.55;font-variant-numeric:tabular-nums}
.skills-file-row.is-skill{background:rgba(108,100,230,.08);font-weight:500}

/* Toast used by catalog install */
.skills-toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);padding:10px 18px;background:var(--bg-secondary,#1e1e1e);color:var(--text-primary,#fff);border:1px solid var(--border-color,#333);border-radius:6px;font-size:13px;box-shadow:0 4px 12px rgba(0,0,0,.3);z-index:10020;animation:skillsToastIn .25s cubic-bezier(.2,1,.3,1)}
.skills-toast.is-error{border-color:rgba(239,68,68,.5);color:#fca5a5}
.skills-toast.is-success{border-color:rgba(34,197,94,.5)}
@keyframes skillsToastIn{from{opacity:0;transform:translate(-50%,10px)}to{opacity:1;transform:translate(-50%,0)}}

/* ── Drag-and-drop overlay (skill package install) ── */
.memory-modal{position:relative}
.memory-drop-overlay{position:absolute;inset:0;display:none;align-items:center;justify-content:center;background:rgba(26,24,20,0.78);backdrop-filter:blur(4px);z-index:50;border-radius:inherit;pointer-events:none}
.memory-modal.is-dragging .memory-drop-overlay{display:flex}
.memory-drop-card{padding:28px 36px;border:2px dashed var(--m-gold);border-radius:8px;background:var(--m-cream);color:var(--m-ink);text-align:center;display:flex;flex-direction:column;align-items:center;gap:10px;box-shadow:4px 4px 0 var(--m-ink);max-width:380px}
.memory-drop-title{font-weight:600;font-size:15px}
.memory-drop-hint{font-size:12px;opacity:.75}
.memory-install-toast{position:absolute;left:50%;bottom:64px;transform:translateX(-50%);padding:10px 16px;background:var(--m-ink);color:var(--m-white);border-radius:4px;font-size:13px;box-shadow:2px 2px 0 var(--m-gold);z-index:60;max-width:80%;animation:memorySlam .25s cubic-bezier(.2,1,.3,1)}
.memory-install-toast.is-error{background:#b91c1c}

/* ── Light theme — already matches since memory-modal uses its own tokens ── */
[data-theme="light"] .memory-modal{border-color:rgba(26,24,20,0.15) !important;box-shadow:4px 4px 16px rgba(0,0,0,0.08) !important}
[data-theme="light"] .memory-modal-header{border-bottom-color:rgba(0,0,0,0.1)}
[data-theme="light"] .memory-modal-footer{border-top-color:rgba(0,0,0,0.1)}
[data-theme="light"] .memory-card{border-color:rgba(0,0,0,0.12);box-shadow:1px 1px 0 rgba(0,0,0,0.05)}
[data-theme="light"] .memory-card:hover{box-shadow:2px 2px 0 rgba(0,0,0,0.08)}
[data-theme="light"] .memory-skeleton{background:linear-gradient(90deg,var(--m-cream) 25%,var(--m-skin) 50%,var(--m-cream) 75%);background-size:200% 100%}
[data-theme="light"] .memory-retry-btn{border-color:rgba(0,0,0,0.15)}
[data-theme="light"] #memoryToggle.active{background:rgba(201,153,63,0.12);color:#a87d2e;border-color:rgba(201,153,63,0.25)}
[data-theme="light"] .memory-badge{background:rgba(201,153,63,0.1);color:#a87d2e;border-color:rgba(201,153,63,0.2)}
[data-theme="light"] .memory-badge .mem-dot{background:#a87d2e}


/* ── Lazy-load sentinel ── */
.lazy-sentinel{display:flex;align-items:center;justify-content:center;padding:18px 0 12px;opacity:.55;transition:opacity .2s}
.lazy-sentinel:hover{opacity:.85}
.lazy-sentinel-text{font-size:12px;color:var(--text-tertiary);letter-spacing:.3px;display:flex;align-items:center;gap:6px}
.lazy-sentinel-text .loading-dots::after{content:'...';animation:lazyDots 1.2s steps(4,end) infinite}
@keyframes lazyDots{0%{content:''}25%{content:'.'}50%{content:'..'}75%{content:'...'}}

/* ══════════════════════════════════════════
   Branch Conversations — 分支对话 (Neural Dendrite)
   ══════════════════════════════════════════ */

/* ── Branch container underneath an assistant message ── */
.branch-zone{margin-top:12px;position:relative;padding-left:0}

/* ── "Add branch" (分支) — now a unified `.msg-action-btn` in the bottom
      action bar (see chat_render.js). Its hover accent matches the branch
      theme colour. ── */
.msg-branch-btn:hover{color:var(--accent);background:var(--accent-subtle)}

/* ── Branch node pills ── */
.branch-nodes{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}
.branch-node{
  position:relative;display:inline-flex;align-items:center;gap:6px;
  padding:6px 14px 6px 10px;
  background:var(--bg-tertiary);border:1px solid var(--border);border-radius:20px;
  font-size:12px;color:var(--text-secondary);cursor:pointer;
  transition:background-color .3s cubic-bezier(.4,0,.2,1),border-color .3s cubic-bezier(.4,0,.2,1),color .3s cubic-bezier(.4,0,.2,1),transform .3s cubic-bezier(.4,0,.2,1),box-shadow .3s cubic-bezier(.4,0,.2,1);
  max-width:280px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.branch-node:hover{background:var(--bg-hover);border-color:var(--accent);color:var(--text-primary);transform:translateY(-1px);box-shadow:0 2px 8px rgba(110,86,207,0.15)}
.branch-node.active{background:var(--accent-subtle);border-color:var(--accent);color:var(--accent)}
.branch-node-icon{font-size:13px;flex-shrink:0}
.branch-node-label{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.branch-node-count{font-size:10px;opacity:0.6;margin-left:2px}
.branch-node-close{
  margin-left:4px;padding:0 2px;font-size:14px;line-height:1;
  color:var(--text-tertiary);cursor:pointer;opacity:0;transition:opacity .2s;
  border:none;background:none;
}
.branch-node:hover .branch-node-close{opacity:0.7}
.branch-node-close:hover{opacity:1;color:var(--error-border)}

/* Pulse dot for active streaming branch */
.branch-node-pulse{
  width:6px;height:6px;border-radius:50%;background:var(--accent);
  animation:branchPulse 1.5s ease-in-out infinite;margin-right:2px;flex-shrink:0;
}
.branch-node.streaming{border-color:var(--accent);box-shadow:0 0 8px rgba(110,86,207,0.3)}
@keyframes branchPulse{0%,100%{opacity:.4;transform:scale(.8)}50%{opacity:1;transform:scale(1.2)}}

/* ── Expanded branch conversation panel ── */
.branch-panel{
  margin-top:8px;
  border:1px solid var(--border);border-radius:var(--radius-sm);
  background:var(--bg-secondary);overflow:hidden;
  animation:branchSlideIn .3s cubic-bezier(.4,0,.2,1);
  box-shadow:0 2px 12px rgba(0,0,0,0.15);
}
@keyframes branchSlideIn{from{opacity:0;max-height:0;transform:translateY(-8px)}to{opacity:1;max-height:2000px;transform:translateY(0)}}

.branch-panel-header{
  display:flex;align-items:center;gap:8px;
  padding:8px 14px;
  background:linear-gradient(135deg,var(--accent-subtle),transparent);
  border-bottom:1px solid var(--border);
  font-size:12px;color:var(--text-secondary);
}
.branch-panel-icon{font-size:14px;flex-shrink:0}
.branch-panel-title{font-weight:600;color:var(--text-primary);flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.branch-panel-back{
  background:none;border:none;color:var(--text-tertiary);cursor:pointer;
  font-size:11px;padding:2px 8px;border-radius:12px;transition:color .2s,background-color .2s;
  display:flex;align-items:center;gap:3px;
}
.branch-panel-back:hover{color:var(--text-primary);background:var(--bg-hover)}
.branch-panel-count{font-size:11px;color:var(--text-tertiary);margin-left:auto;margin-right:4px}
.branch-panel-close{
  background:none;border:none;color:var(--text-tertiary);cursor:pointer;
  font-size:14px;padding:2px 6px;border-radius:var(--radius-xs);transition:color .2s,background-color .2s;line-height:1;
}
.branch-panel-close:hover{color:var(--text-primary);background:var(--bg-hover)}

/* Collapse button (replaces close) */
.branch-panel-collapse{
  background:none;border:1px solid var(--border);color:var(--text-secondary);cursor:pointer;
  font-size:11px;padding:2px 10px;border-radius:12px;transition:color .2s,background-color .2s,border-color .2s;line-height:1.4;
  margin-left:auto;
}
.branch-panel-collapse:hover{color:var(--text-primary);background:var(--bg-hover);border-color:var(--text-tertiary)}

/* Stop button in panel header (during streaming) */
.branch-panel-stop{
  background:none;border:1px solid var(--error-border,#ff5050);color:var(--error,#ff5050);cursor:pointer;
  font-size:11px;padding:2px 10px;border-radius:12px;transition:background-color .2s,border-color .2s;line-height:1.4;
  animation:branchStopPulse 2s ease-in-out infinite;
}
.branch-panel-stop:hover{background:rgba(255,80,80,0.15);border-color:var(--error,#ff5050)}
@keyframes branchStopPulse{0%,100%{opacity:1}50%{opacity:0.7}}

/* Delete button in panel header */
.branch-panel-delete{
  background:none;border:none;color:var(--text-tertiary);cursor:pointer;
  font-size:13px;padding:2px 6px;border-radius:var(--radius-xs);transition:color .2s,opacity .2s,background-color .2s;line-height:1;
  opacity:0.5;
}
.branch-panel-delete:hover{color:var(--error);opacity:1;background:rgba(255,80,80,0.1)}

/* ── Messages inside branch ── */
.branch-messages{max-height:500px;overflow-y:auto;padding:8px 12px;scroll-behavior:smooth}
.branch-messages::-webkit-scrollbar{width:4px}
.branch-messages::-webkit-scrollbar-thumb{background:var(--border);border-radius:2px}

.branch-msg{margin-bottom:8px;padding:6px 10px;border-radius:var(--radius-xs);font-size:13px;line-height:1.6}
.branch-msg.user{background:var(--bg-tertiary);border-left:2px solid var(--user-bubble);color:var(--text-primary)}
.branch-msg.assistant{background:transparent;color:var(--text-primary)}
.branch-msg .branch-msg-header{margin-bottom:2px}
.branch-msg .branch-msg-role{font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.5px;color:var(--text-tertiary);margin-bottom:2px}
.branch-msg .branch-msg-body{font-size:13px;line-height:1.6}
.branch-msg .md-content{font-size:13px}
.branch-msg .md-content p{margin:4px 0}
.branch-msg .md-content pre{font-size:12px}

/* Thinking inside branch */
.branch-thinking{
  margin:4px 0 6px;padding:6px 10px;
  border-left:2px solid var(--thinking-border);
  background:var(--thinking-bg);border-radius:0 var(--radius-xs) var(--radius-xs) 0;
  font-size:11.5px;color:var(--thinking-text);
  max-height:120px;overflow-y:auto;
}
.branch-thinking summary{cursor:pointer;font-size:11px;opacity:0.8}
.branch-thinking-body{white-space:pre-wrap;word-break:break-word;opacity:0.85;margin-top:4px}

/* ── Branch message content ── */
.branch-msg-content{font-size:12.5px;line-height:1.6;color:var(--text-primary);word-break:break-word}
.branch-msg-content.md-content{font-size:12.5px}
.branch-empty{
  padding:24px 16px;text-align:center;
  color:var(--text-tertiary);font-size:12px;font-style:italic;
}
.branch-selection-ctx{
  margin-bottom:8px;padding:8px 12px;
  background:var(--bg-tertiary);border-radius:6px;
  color:var(--text-secondary);font-size:11.5px;font-style:normal;
  text-align:left;line-height:1.5;word-break:break-word;
}

/* ── Branch typing indicator ── */
.branch-typing-indicator{
  display:inline-flex;gap:3px;padding:4px 0;
}
.branch-typing-indicator::after{
  content:"●●●";letter-spacing:2px;
  animation:branchTyping 1.2s ease-in-out infinite;
  color:var(--text-tertiary);font-size:10px;
}
@keyframes branchTyping{0%,100%{opacity:.3}50%{opacity:1}}

/* ── Branch streaming message ── */
.branch-streaming-msg{opacity:0.9}

/* ── Branch mode banner above main input ── */
.branch-mode-banner{
  display:flex;align-items:center;gap:8px;
  padding:6px 16px;
  background:linear-gradient(135deg,var(--accent-subtle),rgba(110,86,207,0.05));
  border-top:1px solid var(--accent);
  font-size:12px;color:var(--accent);
  animation:branchBannerIn .3s ease;
}
@keyframes branchBannerIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
.branch-mode-banner-icon{font-size:16px}
.branch-mode-banner-text{font-weight:500;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.branch-mode-banner-text strong{font-weight:700}
.branch-mode-banner-close{
  background:none;border:1px solid var(--accent);color:var(--accent);
  padding:2px 12px;border-radius:12px;font-size:11px;cursor:pointer;
  transition:background-color .2s,color .2s;flex-shrink:0;
}
.branch-mode-banner-close:hover{background:var(--accent);color:#fff}
.branch-mode-banner-exit{
  background:none;border:1px solid var(--border);color:var(--text-secondary);
  padding:3px 10px;border-radius:4px;cursor:pointer;font-size:11px;
  transition:background-color .2s,color .2s,border-color .2s;white-space:nowrap;font-family:inherit;
}
.branch-mode-banner-exit:hover{background:var(--accent);color:#fff;border-color:var(--accent)}

/* streaming dot on branch node pill */
.branch-node-streaming-dot{
  width:6px;height:6px;border-radius:50%;background:var(--accent);
  animation:branchPulse 1.5s ease-in-out infinite;
}

/* branch streaming body inside panel */
.branch-streaming-body{padding:8px 0}

/* ── Branch input hint (shown in panel) ── */
.branch-input-hint{
  padding:8px 14px;text-align:center;
  color:var(--text-tertiary);font-size:11px;
  border-top:1px solid var(--border);
  background:var(--bg-tertiary);
}
.branch-input-hint span{opacity:0.7}

/* ── Streaming zones inside branch panel ── */
.branch-stream-zone{margin:4px 0}
.branch-stream-zone [data-zone="tool"]{margin-bottom:4px}
.branch-stream-zone [data-zone="status"]{padding:4px 0}
.branch-stream-zone .stream-status{font-size:11.5px;display:flex;align-items:center;gap:6px;color:var(--text-tertiary)}
.branch-stream-zone .pulse{width:6px;height:6px;border-radius:50%;background:var(--accent);animation:branchPulse 1.5s ease-in-out infinite}

/* ── Search/tool rounds inside branch ── */
.branch-search-round{
  margin:4px 0;padding:4px 8px;border-radius:var(--radius-xs);
  background:var(--bg-tertiary);font-size:11.5px;cursor:pointer;
  transition:border-color .2s,opacity .2s;border-left:2px solid var(--border);
}
.branch-search-round.done{border-left-color:var(--accent)}
.branch-search-round.searching{border-left-color:var(--warning-border);opacity:0.8}
.branch-search-round.waiting{border-left-color:var(--warning-border)}
.branch-search-round.expanded .branch-search-results{display:block}
.branch-search-header{display:flex;align-items:center;gap:6px;color:var(--text-secondary)}
.branch-search-count{font-size:10px;opacity:0.6}
.branch-search-waiting{font-size:10px;color:var(--warning-border)}
.branch-search-results{display:none;margin-top:4px;padding-top:4px;border-top:1px solid var(--border);font-size:11px;color:var(--text-tertiary)}
.branch-search-query{color:var(--text-secondary);font-weight:500}
.branch-search-link{color:var(--accent);text-decoration:none;display:block;margin:2px 0}
.branch-search-link:hover{text-decoration:underline}
.branch-search-results a{color:var(--accent);text-decoration:none}
.branch-search-results a:hover{text-decoration:underline}

/* ── Branch tool approval buttons ── */
.branch-search-approval{display:flex;gap:6px;margin-top:4px}
.branch-approve-btn,.branch-reject-btn{
  padding:2px 10px;border-radius:10px;font-size:10px;
  cursor:pointer;border:1px solid;transition:background-color .2s,color .2s;
}
.branch-approve-btn{border-color:var(--success-border);color:var(--success-border);background:transparent}
.branch-approve-btn:hover{background:var(--success-border);color:#fff}
.branch-reject-btn{border-color:var(--error-border);color:var(--error-border);background:transparent}
.branch-reject-btn:hover{background:var(--error-border);color:#fff}
.branch-approval{display:flex;gap:8px;margin-top:6px;padding:4px 0}
.branch-approval button{padding:4px 12px;border-radius:12px;font-size:11px;cursor:pointer;border:1px solid var(--border);background:var(--bg-tertiary);color:var(--text-secondary);transition:background-color .15s,color .15s,border-color .15s}
.branch-approval button:hover{background:var(--accent-subtle);color:var(--accent);border-color:var(--accent)}

/* ── Branch input area (legacy — kept for compat) ── */
.branch-input-area{
  display:flex;gap:6px;padding:8px 12px;
  border-top:1px solid var(--border);
  background:var(--bg-tertiary);
}
.branch-input{
  flex:1;padding:6px 12px;
  background:var(--bg-primary);border:1px solid var(--border);border-radius:16px;
  color:var(--text-primary);font-size:12.5px;font-family:inherit;
  outline:none;resize:none;min-height:32px;max-height:80px;line-height:1.4;
}
.branch-input:focus{border-color:var(--accent)}
.branch-input::placeholder{color:var(--text-tertiary)}
.branch-send-btn{
  width:32px;height:32px;border-radius:50%;
  background:var(--accent);border:none;color:#fff;cursor:pointer;
  display:flex;align-items:center;justify-content:center;
  transition:background-color .2s,transform .2s;flex-shrink:0;
}
.branch-send-btn:hover{background:var(--accent-hover);transform:scale(1.05)}
.branch-send-btn:disabled{opacity:0.4;cursor:not-allowed;transform:none}
.branch-send-btn svg{width:14px;height:14px}

/* ── Streaming indicator inside branch ── */
.branch-streaming{
  padding:8px 12px;display:flex;align-items:center;gap:8px;
  font-size:11.5px;color:var(--text-tertiary);
}
.branch-streaming .pulse{width:6px;height:6px;border-radius:50%;background:var(--accent);animation:branchPulse 1.5s ease-in-out infinite}

/* ── Connection line from node to panel (visual dendrite) ── */
.branch-connector{
  width:1px;height:8px;
  background:linear-gradient(to bottom,var(--border),var(--accent-subtle));
  margin-left:24px;
}

/* ── Light theme overrides ── */
[data-theme="light"] .branch-node{background:rgba(0,0,0,0.03);border-color:rgba(0,0,0,0.08)}
[data-theme="light"] .branch-node:hover{background:rgba(110,86,207,0.06);border-color:var(--accent)}
[data-theme="light"] .branch-panel{background:#fff;box-shadow:0 2px 12px rgba(0,0,0,0.08)}
[data-theme="light"] .branch-msg.user{background:rgba(0,0,0,0.03);border-left-color:var(--user-bubble)}
[data-theme="light"] .branch-input{background:#fff}

/* ── Text Selection Popup (Branch / Reply) ── */
.selection-popup{
  position:fixed;z-index:9999;
  display:flex;gap:0;
  background:var(--bg-secondary);border:1px solid var(--border);
  border-radius:8px;box-shadow:0 4px 20px rgba(0,0,0,0.25);
  overflow:hidden;animation:selPopIn .15s ease;
  pointer-events:auto;
}
@keyframes selPopIn{from{opacity:0;transform:scale(.9) translateY(4px)}to{opacity:1;transform:scale(1) translateY(0)}}
.selection-popup-btn{
  display:flex;align-items:center;gap:5px;
  padding:7px 14px;font-size:12px;font-weight:500;
  color:var(--text-primary);background:transparent;
  border:none;cursor:pointer;transition:background-color .15s,color .15s;
  white-space:nowrap;font-family:inherit;
}
.selection-popup-btn:hover{background:var(--accent-subtle);color:var(--accent)}
.selection-popup-btn:first-child{border-right:1px solid var(--border)}
.selection-popup-btn .sel-icon{font-size:13px}

/* ── Reply Quote — in user message ── */
/* ── Reply Quote Badge — in-message (looks like file upload badge) ── */
.reply-quote-badge{
  display:inline-flex;align-items:center;gap:8px;
  padding:7px 12px;margin-bottom:8px;
  background:var(--thinking-bg);
  border:1px solid var(--thinking-border);
  border-radius:var(--radius-sm);
  max-width:360px;cursor:default;
  transition:border-color .2s;
}
.reply-quote-badge:hover{border-color:var(--accent)}
.reply-quote-badge-icon{font-size:18px;flex-shrink:0}
.reply-quote-badge-info{display:flex;flex-direction:column;gap:1px;min-width:0;overflow:hidden}
.reply-quote-badge-name{font-size:12.5px;font-weight:500;color:var(--text-primary);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.reply-quote-badge-meta{font-size:11px;color:var(--text-tertiary)}

/* ── Reply Quote Container (multi-quote) ── */
.reply-quote-container{
  display:flex;flex-wrap:wrap;gap:6px;
  padding:6px 14px 2px;
}
.reply-quote-container:empty{display:none}
/* ── Reply Quote Chip — floating above input (same file-badge look) ── */
.reply-quote-chip{
  display:inline-flex;align-items:center;gap:6px;
  padding:4px 10px;
  background:var(--thinking-bg);
  border:1px solid var(--thinking-border);
  border-radius:6px;
  max-width:320px;
  font-size:12px;
  animation:quoteChipIn .2s ease;
}
@keyframes quoteChipIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}
.reply-quote-chip-icon{font-size:14px;flex-shrink:0}
.reply-quote-chip-info{display:flex;flex-direction:column;gap:1px;min-width:0;overflow:hidden}
.reply-quote-chip-name{font-size:12px;font-weight:500;color:var(--text-primary);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.reply-quote-chip-meta{font-size:10.5px;color:var(--text-tertiary)}
.reply-quote-chip-close{
  background:none;border:none;color:var(--text-tertiary);cursor:pointer;
  padding:2px 4px;font-size:14px;line-height:1;transition:color .15s;flex-shrink:0;
  border-radius:4px;
}
.reply-quote-chip-close:hover{color:var(--text-primary);background:var(--bg-tertiary)}

/* ── @ button active state in input toolbar ── */
#convRefBtn.has-refs{
  color:#c792ea !important;
  background:rgba(199,146,234,.15);
}
#convRefBtn.has-refs span{
  text-shadow:0 0 6px rgba(199,146,234,.4);
}

/* ── Conversation Reference @ button (sidebar) ── */
.conv-ref{
  color:var(--text-tertiary);transition:color .15s, background .15s;
  font-weight:700;font-size:14px;font-family:-apple-system,BlinkMacSystemFont,sans-serif;
  line-height:1;
}
.conv-ref:hover{
  color:#c792ea;background:rgba(199,146,234,.14);
}

/* ── Conversation Reference Chip Container ── */
.conv-ref-container{
  display:flex;flex-wrap:wrap;gap:6px;
  padding:6px 14px 2px;
}
.conv-ref-container:empty{display:none}

/* ── Conversation Reference Chip ── */
@keyframes convRefChipIn{
  from{opacity:0;transform:translateY(6px) scale(.96)}
  to{opacity:1;transform:translateY(0) scale(1)}
}
.conv-ref-chip{
  display:inline-flex;align-items:center;gap:6px;
  padding:4px 10px;
  background:rgba(199,146,234,.08);
  border:1px solid rgba(199,146,234,.45);
  border-radius:6px;
  font-size:12px;line-height:1.3;
  max-width:280px;min-width:0;
  animation:convRefChipIn .2s ease-out;
  transition:border-color .15s, box-shadow .15s;
}
.conv-ref-chip:hover{
  border-color:rgba(199,146,234,.7);
  box-shadow:0 0 0 2px rgba(199,146,234,.1);
}
.conv-ref-chip-icon{
  font-size:14px;line-height:1;
  color:#c792ea;
  flex-shrink:0;
}
.conv-ref-chip-info{
  display:flex;flex-direction:column;gap:1px;min-width:0;overflow:hidden;
}
.conv-ref-chip-title{
  font-size:12px;font-weight:500;color:var(--text-primary);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.conv-ref-chip-id{
  font-size:10px;color:var(--text-tertiary);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.conv-ref-chip-remove{
  background:none;border:none;color:var(--text-tertiary);cursor:pointer;
  padding:2px 4px;font-size:14px;line-height:1;transition:color .15s, background .15s;flex-shrink:0;
  border-radius:4px;margin-left:auto;
}
.conv-ref-chip-remove:hover{color:#c792ea;background:rgba(199,146,234,.15)}

/* ── Conversation Reference badge (in chat messages) ── */
.conv-ref-badge{
  border-color:rgba(199,146,234,.35) !important;
  background:rgba(199,146,234,.06) !important;
}
.conv-ref-badge:hover{border-color:#c792ea !important}
.conv-ref-badge .reply-quote-badge-icon{filter:none}


/* ── Peer-message provenance banner (chat_render.js) ── */
/* An advisory turn injected by a sibling conversation of the same project. */
.peer-msg-banner{
  display:inline-flex;align-items:center;gap:6px;
  margin:0 0 8px 0;padding:4px 10px;
  border:1px solid rgba(130,170,255,.35);
  background:rgba(130,170,255,.08);
  border-radius:8px;font-size:12px;line-height:1.3;
  color:var(--text-secondary, #9aa4b2);
}
.peer-msg-banner .peer-msg-icon{display:inline-flex;color:#82aaff}
.peer-msg-banner .peer-msg-from{color:#82aaff;font-weight:600}
/* Operator nudge (from the Team panel) — distinct from an agent peer note. */
.peer-msg-banner.peer-msg-banner-operator{border-color:rgba(126,231,135,.4);background:rgba(126,231,135,.09)}
.peer-msg-banner.peer-msg-banner-operator .peer-msg-icon,
.peer-msg-banner.peer-msg-banner-operator .peer-msg-from{color:#7ee787}

/* ── Conversation Reference Picker Popover ── */
.conv-ref-picker{
  position:fixed;z-index:10000;
  display:flex;flex-direction:column;
  background:var(--bg-secondary);
  border:1px solid var(--border);
  border-radius:var(--radius-md, 12px);
  box-shadow:0 12px 40px rgba(0,0,0,.5), 0 0 0 1px rgba(199,146,234,.15);
  overflow:hidden;
  animation:convRefPickerIn .18s ease-out;
}
@keyframes convRefPickerIn{
  from{opacity:0;transform:translateY(8px) scale(.97)}
  to{opacity:1;transform:translateY(0) scale(1)}
}
.conv-ref-picker-header{
  display:flex;align-items:center;justify-content:space-between;
  padding:12px 14px 8px;
  border-bottom:1px solid var(--border);
}
.conv-ref-picker-title{
  font-size:13px;font-weight:600;color:#c792ea;
}
.conv-ref-picker-close{
  background:none;border:none;color:var(--text-tertiary);
  font-size:20px;line-height:1;cursor:pointer;padding:0 4px;
  transition:color .15s;
}
.conv-ref-picker-close:hover{color:var(--text-primary)}
.conv-ref-picker-search{
  padding:8px 12px;
}
.conv-ref-picker-search input{
  width:100%;box-sizing:border-box;
  padding:8px 12px;
  background:var(--bg-primary);
  border:1px solid var(--border);border-radius:var(--radius-sm, 8px);
  color:var(--text-primary);font-size:13px;
  outline:none;transition:border-color .2s;
}
.conv-ref-picker-search input:focus{
  border-color:#c792ea;
  box-shadow:0 0 0 2px rgba(199,146,234,.15);
}
.conv-ref-picker-search input::placeholder{color:var(--text-tertiary)}
.conv-ref-picker-list{
  flex:1;overflow-y:auto;padding:4px 6px 8px;
  max-height:280px;
}
.conv-ref-picker-item{
  padding:9px 10px;margin:2px 0;
  border-radius:var(--radius-sm, 8px);
  cursor:pointer;transition:background .15s;
}
.conv-ref-picker-item:hover{background:rgba(199,146,234,.08)}
.conv-ref-picker-item.is-referenced{
  background:rgba(199,146,234,.1);
}
.conv-ref-picker-item.is-referenced:hover{
  background:rgba(199,146,234,.06);
}
.conv-ref-picker-item-main{
  display:flex;align-items:center;gap:6px;
}
.conv-ref-picker-item-title{
  font-size:13px;font-weight:500;color:var(--text-primary);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
  flex:1;min-width:0;
}
.conv-ref-picker-item-check{
  font-size:13px;color:#c792ea;font-weight:700;flex-shrink:0;
}
.conv-ref-picker-item-meta{
  display:flex;gap:4px;margin-top:3px;
  font-size:11px;color:var(--text-tertiary);
}
.conv-ref-picker-empty{
  padding:24px 12px;text-align:center;
  font-size:13px;color:var(--text-tertiary);
}

/* Scrollbar for picker list */
.conv-ref-picker-list::-webkit-scrollbar{width:4px}
.conv-ref-picker-list::-webkit-scrollbar-thumb{background:var(--border);border-radius:2px}
.conv-ref-picker-list::-webkit-scrollbar-thumb:hover{background:var(--text-tertiary)}

/* old .edit-reply-quote removed — replaced by .edit-rq-chip */

/* ── Inline branch node (anchored inside content) ── */
.branch-node.inline{
  display:flex;font-size:12px;padding:5px 12px;margin:0;
  width:100%;justify-content:flex-start;box-sizing:border-box;
  max-width:none;border-radius:var(--radius-sm);
}
.branch-anchor-inline{
  display:flex;flex-direction:column;gap:4px;
  margin:8px 0;
  padding:6px 0 6px 10px;
  border-left:2px solid var(--accent);
}

/* ── Reply quote inside branch message ── */
.branch-reply-quote{
  display:inline-flex;align-items:center;gap:6px;
  padding:4px 8px;margin-bottom:4px;
  background:var(--bg-tertiary);
  border:1px solid var(--border);border-radius:var(--radius-xs);
  font-size:11px;max-width:260px;
}
.branch-reply-quote-icon{font-size:13px;flex-shrink:0}
.branch-reply-quote-text{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--text-tertiary)}

[data-theme="light"] .selection-popup{background:#fff;box-shadow:0 4px 20px rgba(0,0,0,0.12)}
[data-theme="light"] .reply-quote-badge{background:rgba(0,0,0,0.03);border-color:rgba(0,0,0,0.08)}
