/* ══════════════════════════════════════════
   Trading Advisor 投资持仓顾问
   ══════════════════════════════════════════ */

/* ══════════════════════════════════════════
   ★ Endpoint Mode (Autonomous AI + Self-Review)
   ══════════════════════════════════════════ */
#endpointToggle.active{
  color:#f59e0b;
  background:rgba(245,158,11,0.1);
  border-color:rgba(245,158,11,0.3);
}
/* Iteration banner inside streaming message */
.ep-iter-banner{
  display:inline-flex;
  align-items:center;
  gap:6px;
  padding:4px 12px;
  margin-bottom:8px;
  background:rgba(245,158,11,0.08);
  border:1px solid rgba(245,158,11,0.2);
  border-radius:20px;
  font-size:11px;
  font-weight:700;
  font-family:'JetBrains Mono',monospace;
  color:#f59e0b;
  letter-spacing:.02em;
}
/* Review score display */
.ep-review-score{
  display:inline-flex;
  align-items:center;
  gap:4px;
  padding:2px 8px;
  border-radius:12px;
  font-size:10px;
  font-weight:800;
  font-family:'JetBrains Mono',monospace;
}
.ep-review-score.approved{background:rgba(34,197,94,0.1);color:#22c55e;border:1px solid rgba(34,197,94,0.2)}
.ep-review-score.rejected{background:rgba(239,68,68,0.1);color:#ef4444;border:1px solid rgba(239,68,68,0.2)}
/* Endpoint result tag on rendered messages */
.endpoint-result-tag{
  display:inline-flex;
  align-items:center;
  gap:4px;
  padding:3px 10px;
  border-radius:12px;
  font-size:10px;
  font-weight:700;
  font-family:'JetBrains Mono',monospace;
  margin-left:6px;
}
.endpoint-result-tag.approved{background:rgba(34,197,94,0.08);color:#22c55e}
.endpoint-result-tag.max_iterations{background:rgba(245,158,11,0.08);color:#f59e0b}
.endpoint-result-tag.stuck{background:rgba(239,68,68,0.08);color:#ef4444}

/* ── Critic verdict badges ── */
.ep-verdict-badge{
  display:inline-flex;
  align-items:center;
  gap:3px;
  padding:2px 8px;
  border-radius:10px;
  font-size:10px;
  font-weight:700;
  font-family:'JetBrains Mono',monospace;
  margin-left:6px;
  vertical-align:middle;
}
.ep-verdict-stop{background:rgba(34,197,94,0.10);color:#22c55e;border:1px solid rgba(34,197,94,0.25)}
.ep-verdict-continue{background:rgba(245,158,11,0.10);color:#f59e0b;border:1px solid rgba(245,158,11,0.25)}
.ep-verdict-stuck{background:rgba(239,68,68,0.10);color:#ef4444;border:1px solid rgba(239,68,68,0.25)}
.ep-verdict-planner{background:rgba(99,102,241,0.10);color:#6366f1;border:1px solid rgba(99,102,241,0.25)}
.ep-verdict-replan{background:rgba(217,119,6,0.12);color:#d97706;border:1px solid rgba(217,119,6,0.30)}
/* Planner message styling — indigo accent to distinguish from worker */
.ep-planner-msg{
  border-left:2px solid rgba(99,102,241,0.35);
}
.ep-planner-msg .message-avatar{
  color:#6366f1;
  width:40px;height:40px;
}
.ep-planner-msg .message-role{
  color:#6366f1;
}
.ep-planner-msg .md-content{
  color:var(--text-secondary);
}
/* Planner iteration banner variant */
.ep-iter-banner-planner{
  background:rgba(99,102,241,0.08);
  border-color:rgba(99,102,241,0.2);
  color:#6366f1;
}
/* Critic message styling — slightly different background to distinguish from user */
.ep-critic-msg{
  border-left:2px solid rgba(245,158,11,0.35);
}
.ep-critic-msg .message-avatar{
  color:#f59e0b;
  width:40px;height:40px;
}
.ep-critic-msg .md-content{
  color:var(--text-secondary);
}
/* Worker message styling — green accent */
.ep-worker-msg .message-avatar{
  width:40px;height:40px;
}
/* Autopilot virtual user — distinguishable from a real user message but
 * still rendered in the user lane.  Dashed border + cool indigo accent. */
.vu-user-msg{
  opacity:.94;
}
.vu-user-msg .message-avatar{
  color:#f59e0b;
  width:40px;height:40px;
}
.vu-user-msg .message-role{
  color:#f59e0b;
  font-style:italic;
}
/* Header above the autopilot's investigation tool panel inside a VU
 * message.  Tells the user "this isn't normal user content — it's the
 * tool calls Autopilot ran before composing the reply". */
.vu-investigation-header{
  display:flex;align-items:center;gap:6px;
  margin:6px 0 4px 0;
  font-size:11px;
  color:#818cf8;
  letter-spacing:.02em;
  text-transform:uppercase;
  opacity:.85;
}
.vu-investigation-icon{
  display:inline-block;width:10px;height:10px;border-radius:50%;
  background:rgba(129,140,248,0.35);
  box-shadow:0 0 0 3px rgba(129,140,248,0.10);
}
.vu-investigation-label{font-weight:600;}
/* Provenance boundary header above the VU's REPLY text.  The
 * investigation (indigo, above) + thinking (below) are display-only; only
 * this reply is fed to the agent as its next message.  Green "sent" accent
 * contrasts with the indigo "private process" accent so the human reads the
 * boundary at a glance. */
.vu-handoff-header{
  display:flex;align-items:center;gap:6px;
  margin:8px 0 4px 0;
  font-size:11px;
  color:#34d399;
  letter-spacing:.02em;
  text-transform:uppercase;
  opacity:.9;
}
.vu-handoff-icon{flex-shrink:0;opacity:.85;}
.vu-handoff-label{font-weight:600;}
/* ── VU provenance: PRIVATE zone (collapsible) ──
 * Wraps the autopilot's investigation tool panel + private reasoning into a
 * single default-collapsed container. The dashed indigo frame + "Private ·
 * not sent" summary make it unmistakable that NONE of this reaches the agent
 * (only the reply below does — see conv_message_builder._build_user_message).*/
.vu-private-zone{
  margin:6px 0;
  border:1px dashed rgba(129,140,248,0.35);
  border-radius:8px;
  background:rgba(129,140,248,0.04);
  overflow:hidden;
}
.vu-private-summary{
  display:flex;align-items:center;gap:6px;
  padding:6px 10px;
  cursor:pointer;
  list-style:none;
  font-size:11px;
  color:#818cf8;
  letter-spacing:.02em;
  text-transform:uppercase;
  user-select:none;
}
.vu-private-summary::-webkit-details-marker{display:none;}
.vu-private-icon{flex-shrink:0;opacity:.85;}
.vu-private-label{font-weight:600;flex:1;}
.vu-private-toggle{font-size:9px;opacity:.7;transition:transform .15s ease;}
.vu-private-zone[open] .vu-private-toggle{transform:rotate(180deg);}
.vu-private-body{padding:2px 10px 8px 10px;}
.vu-private-body .vu-investigation-header{margin-top:2px;}
/* ── VU provenance: SENT zone (the reply that reaches the agent) ──
 * Bounds the handoff header + reply markdown in a green-accented block so the
 * "this is what's sent" region is visually separate from the private zone. */
.vu-sent-zone{
  margin:8px 0 2px 0;
  border-left:2px solid rgba(52,211,153,0.55);
  padding-left:10px;
}
.vu-sent-zone .vu-handoff-header{margin-top:0;}
/* ── Autopilot run fold ──────────────────────────────────────────────
 * Collapses a concluded autopilot run's VU<->agent transcript into one
 * <details>, leaving [human msg → summary report] as the visible spine. */
.autopilot-run-fold{
  margin:8px 0;
  border:1px solid rgba(129,140,248,0.30);
  border-radius:10px;
  background:rgba(129,140,248,0.045);
  overflow:hidden;
}
.autopilot-run-fold-summary{
  display:flex;align-items:center;gap:8px;
  padding:8px 12px;
  cursor:pointer;
  list-style:none;
  font-size:12px;
  color:#c7d2fe;
  user-select:none;
}
.autopilot-run-fold-summary::-webkit-details-marker{display:none;}
.autopilot-run-fold-summary .apf-icon{flex-shrink:0;opacity:.9;}
.autopilot-run-fold-summary .apf-label{font-weight:600;letter-spacing:.02em;}
.autopilot-run-fold-summary .apf-count{
  font-family:var(--font-mono,monospace);
  font-size:11px;
  background:rgba(129,140,248,0.22);
  color:#e0e7ff;
  border-radius:6px;
  padding:1px 7px;
}
.autopilot-run-fold-summary .apf-hint{font-size:11px;opacity:.8;flex:1;}
.autopilot-run-fold-summary .apf-incomplete{
  display:inline-flex;align-items:center;gap:4px;
  font-size:11px;font-weight:600;
  color:#b45309;background:rgba(245,158,11,0.15);
  padding:1px 7px;border-radius:10px;
}
.autopilot-run-fold-summary .apf-incomplete svg{flex-shrink:0;}
.autopilot-run-fold-summary .apf-summarize-btn{
  font-size:11px;
  border:1px solid rgba(129,140,248,0.45);
  background:transparent;
  color:#c7d2fe;
  border-radius:6px;
  padding:2px 9px;
  cursor:pointer;
}
.autopilot-run-fold-summary .apf-summarize-btn:hover{
  background:rgba(129,140,248,0.15);
}
.autopilot-run-fold-summary .apf-summarize-btn:disabled{opacity:.5;cursor:default;}
/* "View report" button — opens the close-out debrief in a sub-window. Shares
 * the summarize button's visual language plus a leading document glyph. */
.autopilot-run-fold-summary .apf-report-btn{
  display:inline-flex;align-items:center;gap:5px;
  font-size:11px;
  border:1px solid rgba(129,140,248,0.45);
  background:rgba(129,140,248,0.08);
  color:#c7d2fe;
  border-radius:6px;
  padding:2px 9px;
  cursor:pointer;
}
.autopilot-run-fold-summary .apf-report-btn:hover{background:rgba(129,140,248,0.2);}
.autopilot-run-fold-summary .apf-report-btn svg{flex-shrink:0;opacity:.9;}
.autopilot-run-fold-summary .apf-toggle{font-size:9px;opacity:.85;transition:transform .15s ease;}
.autopilot-run-fold[open] .autopilot-run-fold-summary .apf-toggle{transform:rotate(180deg);}

/* Light theme: the base indigo hex values are light-on-light over the cream
 * --bg-primary (#f4f2ed) — swap to dark indigo (matches --accent #6366f1). */
